/* ==============================================================
   Multi AI Chat - Cloudflare Worker backend.

   Same contract as app.py: the browser only ever talks to this
   Worker, and HF_TOKEN lives in the Worker's secrets. The frontend
   is embedded below by build_worker.py, so the whole site is one
   file that can be pasted into the Cloudflare dashboard.
   ============================================================== */
'use strict';

const ASSETS = {"index.html": "<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#05060f\">\n<meta name=\"description\" content=\"Multi AI Chat — общайтесь с нейросетями Hugging Face: DeepSeek, Qwen, Llama, Mistral, Gemma и другими.\">\n<title>Multi AI Chat<\/title>\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%234f7cff'/%3E%3Cstop offset='1' stop-color='%23a855f7'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='64' height='64' rx='16' fill='url(%23g)'/%3E%3Cpath d='M18 24h28M18 32h20M18 40h24' stroke='white' stroke-width='5' stroke-linecap='round'/%3E%3C/svg%3E\">\n<link rel=\"stylesheet\" href=\"/static/styles.css\">\n<\/head>\n<body>\n\n<div class=\"app\">\n\n  <!-- ─────────────── Sidebar ─────────────── -->\n  <aside class=\"sidebar\" id=\"sidebar\" aria-label=\"Панель чатов\">\n    <div class=\"sidebar-top\">\n      <div class=\"brand\">\n        <span class=\"brand-mark\" aria-hidden=\"true\"><\/span>\n        <span class=\"brand-text\">Multi&nbsp;AI&nbsp;Chat<\/span>\n      <\/div>\n      <button class=\"icon-btn sidebar-close\" id=\"sidebarClose\" aria-label=\"Закрыть меню\">✕<\/button>\n    <\/div>\n\n    <button class=\"btn-new\" id=\"newChatBtn\">\n      <span class=\"plus\" aria-hidden=\"true\">+<\/span> Новый чат\n    <\/button>\n\n    <div class=\"search-box\">\n      <svg viewBox=\"0 0 24 24\" class=\"search-icon\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M20 20l-3.5-3.5\"/><\/svg>\n      <input type=\"search\" id=\"searchInput\" placeholder=\"Поиск\" aria-label=\"Поиск по чатам\" autocomplete=\"off\">\n    <\/div>\n\n    <div class=\"section-label\">История чатов<\/div>\n    <nav class=\"chat-list\" id=\"chatList\" aria-label=\"История чатов\"><\/nav>\n\n    <div class=\"sidebar-foot\">\n      <button class=\"foot-btn\" id=\"settingsBtn\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.7 1.7 0 00.3 1.9l.1.1a2 2 0 11-2.8 2.8l-.1-.1a1.7 1.7 0 00-1.9-.3 1.7 1.7 0 00-1 1.5v.2a2 2 0 11-4 0v-.1a1.7 1.7 0 00-1.1-1.5 1.7 1.7 0 00-1.9.3l-.1.1a2 2 0 11-2.8-2.8l.1-.1a1.7 1.7 0 00.3-1.9 1.7 1.7 0 00-1.5-1H2a2 2 0 110-4h.1A1.7 1.7 0 003.6 9a1.7 1.7 0 00-.3-1.9l-.1-.1a2 2 0 112.8-2.8l.1.1a1.7 1.7 0 001.9.3H8a1.7 1.7 0 001-1.5V3a2 2 0 114 0v.1a1.7 1.7 0 001 1.5 1.7 1.7 0 001.9-.3l.1-.1a2 2 0 112.8 2.8l-.1.1a1.7 1.7 0 00-.3 1.9V9a1.7 1.7 0 001.5 1h.2a2 2 0 110 4H21a1.7 1.7 0 00-1.5 1z\"/><\/svg>\n        Настройки\n      <\/button>\n      <button class=\"foot-btn danger\" id=\"clearAllBtn\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14\"/><\/svg>\n        Очистить историю\n      <\/button>\n    <\/div>\n  <\/aside>\n\n  <div class=\"scrim\" id=\"scrim\" hidden><\/div>\n\n  <!-- ─────────────── Main ─────────────── -->\n  <main class=\"main\">\n    <header class=\"topbar\">\n      <button class=\"icon-btn menu-btn\" id=\"menuBtn\" aria-label=\"Открыть меню\">☰<\/button>\n\n      <div class=\"model-info\">\n        <div class=\"model-name\" id=\"modelName\">—<\/div>\n        <div class=\"model-status\" id=\"modelStatus\">\n          <span class=\"dot\" aria-hidden=\"true\"><\/span><span id=\"statusText\">Online<\/span>\n        <\/div>\n      <\/div>\n\n      <button class=\"btn-model\" id=\"pickModelBtn\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h10\"/><\/svg>\n        <span>Выбрать модель<\/span>\n      <\/button>\n    <\/header>\n\n    <div class=\"arena\" aria-hidden=\"true\"><span class=\"pokeball-bg\"><\/span><\/div>\n    <div class=\"messages\" id=\"messages\" role=\"log\" aria-live=\"polite\"><\/div>\n\n    <div class=\"composer-wrap\">\n      <div class=\"composer\" id=\"composer\">\n        <textarea id=\"input\" rows=\"1\" placeholder=\"Напишите сообщение...\" aria-label=\"Сообщение\"><\/textarea>\n        <button class=\"btn-send\" id=\"sendBtn\" aria-label=\"Отправить\" disabled>\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 12L4 4l6 8-6 8z\"/><\/svg>\n        <\/button>\n      <\/div>\n      <button class=\"btn-stop\" id=\"stopBtn\" hidden>\n        <span class=\"stop-square\" aria-hidden=\"true\"><\/span> Остановить\n      <\/button>\n      <div class=\"composer-hint\">\n        <kbd>Enter<\/kbd> — отправить · <kbd>Shift<\/kbd>+<kbd>Enter<\/kbd> — новая строка\n      <\/div>\n    <\/div>\n  <\/main>\n<\/div>\n\n<!-- ─────────────── Model picker ─────────────── -->\n<div class=\"modal\" id=\"modelModal\" hidden>\n  <div class=\"modal-card modal-wide\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modelModalTitle\">\n    <header class=\"modal-head\">\n      <h2 id=\"modelModalTitle\">Выбор нейросети<\/h2>\n      <button class=\"icon-btn\" data-close aria-label=\"Закрыть\">✕<\/button>\n    <\/header>\n\n    <div class=\"modal-search\">\n      <svg viewBox=\"0 0 24 24\" class=\"search-icon\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M20 20l-3.5-3.5\"/><\/svg>\n      <input type=\"search\" id=\"modelSearch\" placeholder=\"Поиск модели или Model ID\" autocomplete=\"off\">\n    <\/div>\n\n    <div class=\"picker-featured\">\n      <div class=\"picker-featured-label\">Быстрый выбор<\/div>\n      <div class=\"starters starters-compact\" id=\"pickerStarters\"><\/div>\n    <\/div>\n\n    <div class=\"picker\">\n      <nav class=\"picker-cats\" id=\"pickerCats\" aria-label=\"Категории\"><\/nav>\n      <div class=\"picker-models\" id=\"pickerModels\"><\/div>\n    <\/div>\n\n    <footer class=\"modal-foot custom-model\">\n      <label for=\"customModel\">Добавить свою модель по Hugging Face Model ID<\/label>\n      <div class=\"custom-row\">\n        <input type=\"text\" id=\"customModel\" placeholder=\"deepseek-ai/DeepSeek-V3-0324\" autocomplete=\"off\" spellcheck=\"false\">\n        <button class=\"btn-primary\" id=\"addModelBtn\">Добавить<\/button>\n      <\/div>\n    <\/footer>\n  <\/div>\n<\/div>\n\n<!-- ─────────────── Settings ─────────────── -->\n<div class=\"modal\" id=\"settingsModal\" hidden>\n  <div class=\"modal-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"settingsTitle\">\n    <header class=\"modal-head\">\n      <h2 id=\"settingsTitle\">Настройки<\/h2>\n      <button class=\"icon-btn\" data-close aria-label=\"Закрыть\">✕<\/button>\n    <\/header>\n\n    <div class=\"modal-body\">\n      <div class=\"field\">\n        <label>Стиль оформления<\/label>\n        <div class=\"themes\" id=\"themePicker\"><\/div>\n        <p class=\"hint\">Меняет оформление всего чата.<\/p>\n      <\/div>\n\n      <div class=\"field\">\n        <label for=\"systemPrompt\">System Prompt<\/label>\n        <textarea id=\"systemPrompt\" rows=\"4\" placeholder=\"Ты полезный ассистент. Отвечай на русском языке.\"><\/textarea>\n        <p class=\"hint\">Задаёт характер и правила ответа модели.<\/p>\n      <\/div>\n\n      <div class=\"field\">\n        <label for=\"temperature\">Temperature <output id=\"temperatureOut\">0.7<\/output><\/label>\n        <input type=\"range\" id=\"temperature\" min=\"0\" max=\"2\" step=\"0.05\" value=\"0.7\">\n        <p class=\"hint\">Ниже — точнее и предсказуемее, выше — креативнее.<\/p>\n      <\/div>\n\n      <div class=\"field\">\n        <label for=\"maxTokens\">Max Tokens <output id=\"maxTokensOut\">2048<\/output><\/label>\n        <input type=\"range\" id=\"maxTokens\" min=\"128\" max=\"8192\" step=\"128\" value=\"2048\">\n        <p class=\"hint\">Максимальная длина ответа.<\/p>\n      <\/div>\n\n      <div class=\"field\">\n        <label for=\"topP\">Top P <output id=\"topPOut\">0.95<\/output><\/label>\n        <input type=\"range\" id=\"topP\" min=\"0.05\" max=\"1\" step=\"0.05\" value=\"0.95\">\n        <p class=\"hint\">Отсечение маловероятных слов.<\/p>\n      <\/div>\n    <\/div>\n\n    <footer class=\"modal-foot\">\n      <button class=\"btn-ghost\" id=\"resetSettings\">Сбросить<\/button>\n      <button class=\"btn-primary\" data-close>Готово<\/button>\n    <\/footer>\n  <\/div>\n<\/div>\n\n<!-- ─────────────── Rename ─────────────── -->\n<div class=\"modal\" id=\"renameModal\" hidden>\n  <div class=\"modal-card modal-narrow\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"renameTitle\">\n    <header class=\"modal-head\">\n      <h2 id=\"renameTitle\">Переименовать чат<\/h2>\n      <button class=\"icon-btn\" data-close aria-label=\"Закрыть\">✕<\/button>\n    <\/header>\n    <div class=\"modal-body\">\n      <div class=\"field\">\n        <input type=\"text\" id=\"renameInput\" maxlength=\"80\" aria-label=\"Название чата\">\n      <\/div>\n    <\/div>\n    <footer class=\"modal-foot\">\n      <button class=\"btn-ghost\" data-close>Отмена<\/button>\n      <button class=\"btn-primary\" id=\"renameSave\">Сохранить<\/button>\n    <\/footer>\n  <\/div>\n<\/div>\n\n<div class=\"toasts\" id=\"toasts\" aria-live=\"assertive\"><\/div>\n\n<script src=\"/static/app.js\"><\/script>\n<\/body>\n<\/html>\n", "styles.css": "/* ══════════════ Multi AI Chat — Pokémon theme ══════════════\n   Bright, game-like surfaces on a deep navy stage: yellow / blue / red\n   accents, chunky pressable buttons, TCG-style model cards. Body copy\n   stays white-on-navy or dark-on-bright so everything reads cleanly.\n   ═══════════════════════════════════════════════════════════ */\n:root{\n  --bg:#070f26;\n  --bg-2:#0b1733;\n  --panel:#122246;\n  --panel-2:#182c57;\n  --raised:#1f386b;\n  --line:#2a4783;\n  --line-soft:#223a6f;\n\n  --text:#ffffff;\n  --muted:#b3c9ef;\n  --faint:#7e97c7;\n\n  --yellow:#ffcb05;\n  --yellow-2:#ffe259;\n  --yellow-deep:#d99e00;\n  --blue:#3d8bff;\n  --blue-2:#6fb0ff;\n  --blue-deep:#1b4f9c;\n  --red:#ff4d4d;\n  --red-2:#ff7a6b;\n  --red-deep:#c0260a;\n  --green:#3ddc84;\n  --green-deep:#189e57;\n\n  --ink:#0a1a33;                     /* dark text used on bright surfaces */\n  --edge:#0a1428;                    /* the dark outline around raised pieces */\n  --code-bg:#060d1f;\n  --err-bg:#2a1430;\n  --grad:linear-gradient(135deg,var(--blue) 0%,var(--blue-deep) 100%);\n  --grad-warm:linear-gradient(135deg,var(--yellow-2) 0%,var(--yellow) 55%,var(--yellow-deep) 100%);\n  --grad-hot:linear-gradient(135deg,var(--red-2) 0%,var(--red) 50%,var(--red-deep) 100%);\n\n  --c1:linear-gradient(150deg,#fff3a8,#ffcb05 62%,#ffb300); --c1d:#b07c00;\n  --c2:linear-gradient(150deg,#ffc39b,#ff7043 60%,#f4511e); --c2d:#a3300c;\n  --c3:linear-gradient(150deg,#b3ddff,#4da3ff 58%,#2a75bb); --c3d:#14508f;\n  --c4:linear-gradient(150deg,#ccf0a0,#7cc84f 58%,#4caf50); --c4d:#2c7330;\n  --c5:linear-gradient(150deg,#bcd2ff,#5b7cfa 58%,#3b4fd8); --c5d:#222f8c;\n  --c6:linear-gradient(150deg,#f3f4f6,#c8ccd4 58%,#9aa1ad); --c6d:#666d78;\n\n  --r-s:10px; --r-m:14px; --r-l:20px; --r-xl:26px;\n  --sidebar-w:292px;\n  --shadow:0 20px 50px rgba(0,0,0,.6);\n  --font:\"Inter\",\"SF Pro Display\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Ubuntu,\"Helvetica Neue\",Arial,sans-serif;\n  --mono:\"JetBrains Mono\",\"SFMono-Regular\",Menlo,Consolas,\"Liberation Mono\",monospace;\n}\n\n*{box-sizing:border-box}\nhtml,body{height:100%}\n/* the hidden attribute must beat the display rules below */\n[hidden]{display:none!important}\nbutton,input,textarea{font:inherit;color:inherit}\nbody{\n  margin:0;\n  font-family:var(--font);\n  background:var(--bg);\n  color:var(--text);\n  -webkit-font-smoothing:antialiased;\n  overscroll-behavior:none;\n}\n/* stage lighting + a faint poké-dot field */\nbody::before{\n  content:\"\";position:fixed;inset:0;z-index:0;pointer-events:none;\n  background:\n    radial-gradient(900px 520px at 10% -10%,rgba(255,203,5,.16),transparent 60%),\n    radial-gradient(820px 480px at 92% 0%,rgba(61,139,255,.20),transparent 62%),\n    radial-gradient(760px 520px at 55% 112%,rgba(255,77,77,.14),transparent 62%),\n    radial-gradient(circle at 50% 50%,rgba(255,255,255,.035) 1.5px,transparent 1.6px) 0 0/34px 34px;\n}\nbutton{cursor:pointer;border:0;background:none}\nsvg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n::-webkit-scrollbar{width:10px;height:10px}\n::-webkit-scrollbar-thumb{background:var(--raised);border-radius:99px;border:3px solid transparent;background-clip:content-box}\n::-webkit-scrollbar-thumb:hover{background:var(--line);background-clip:content-box}\n::-webkit-scrollbar-track{background:transparent}\n\n.app{position:relative;z-index:1;display:flex;height:100dvh;overflow:hidden}\n\n/* ══════════════ Poké-ball marks ══════════════ */\n.brand-mark,.welcome-logo{\n  position:relative;flex:none;border-radius:50%;\n  background:linear-gradient(#ff4d4d 0 49.5%,#12203f 49.5% 50.5%,#fff 50.5% 100%);\n  border:2.5px solid var(--edge);\n  box-shadow:0 5px 0 rgba(0,0,0,.35),inset 0 -3px 8px rgba(0,0,0,.25);\n}\n.brand-mark::after,.welcome-logo::after{\n  content:\"\";position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);\n  width:32%;height:32%;border-radius:50%;background:#fff;\n  border:2.5px solid var(--edge);box-shadow:0 0 0 2px rgba(255,255,255,.55);\n}\n.brand-mark{width:30px;height:30px}\n.welcome-logo{width:76px;height:76px;margin:0 auto 20px;animation:wobble 4.5s ease-in-out infinite}\n@keyframes wobble{\n  0%,88%,100%{transform:rotate(0)}\n  91%{transform:rotate(-13deg)}94%{transform:rotate(11deg)}97%{transform:rotate(-6deg)}\n}\n/* watermark behind the conversation */\n.arena{position:absolute;inset:0;pointer-events:none;overflow:hidden;z-index:0}\n.pokeball-bg{\n  position:absolute;top:-130px;right:-130px;width:420px;height:420px;border-radius:50%;\n  background:linear-gradient(#fff 0 49.2%,transparent 49.2% 50.8%,#fff 50.8% 100%);\n  opacity:.028;border:14px solid #fff;\n  animation:spin 90s linear infinite;\n}\n@keyframes spin{to{transform:rotate(360deg)}}\n\n/* ══════════════ Sidebar ══════════════ */\n.sidebar{\n  position:relative;z-index:2;\n  width:var(--sidebar-w);flex:0 0 var(--sidebar-w);\n  display:flex;flex-direction:column;gap:12px;padding:14px 12px;\n  background:linear-gradient(180deg,var(--bg-2),var(--bg));\n  border-right:3px solid var(--line);\n  box-shadow:inset -1px 0 0 rgba(255,203,5,.25);\n}\n.sidebar-top{display:flex;align-items:center;justify-content:space-between;padding:2px 4px 0}\n.brand{display:flex;align-items:center;gap:10px;font-weight:800;font-size:16px;letter-spacing:.2px}\n.brand-text{\n  background:var(--grad-warm);-webkit-background-clip:text;background-clip:text;color:transparent;\n  text-shadow:0 2px 0 rgba(0,0,0,.25);\n}\n.sidebar .sidebar-close{display:none}\n\n/* chunky pressable button */\n.btn-new{\n  display:flex;align-items:center;justify-content:center;gap:8px;\n  padding:13px 14px;border-radius:var(--r-m);font-weight:800;font-size:15px;\n  background:var(--grad-warm);color:var(--ink);\n  border:2.5px solid var(--edge);\n  box-shadow:0 5px 0 var(--yellow-deep),0 12px 22px rgba(255,203,5,.26);\n  transition:transform .12s ease,box-shadow .12s ease,filter .12s ease;\n}\n.btn-new:hover{filter:brightness(1.05);transform:translateY(-2px);box-shadow:0 7px 0 var(--yellow-deep),0 16px 28px rgba(255,203,5,.34)}\n.btn-new:active{transform:translateY(4px);box-shadow:0 1px 0 var(--yellow-deep)}\n.btn-new .plus{font-size:19px;line-height:1;margin-top:-2px}\n\n.search-box{position:relative;display:flex;align-items:center}\n.search-box .search-icon{position:absolute;left:12px;width:16px;height:16px;color:var(--faint)}\n.search-box input{\n  width:100%;padding:11px 12px 11px 35px;border-radius:var(--r-m);\n  background:var(--panel);border:2px solid var(--line);color:var(--text);\n  outline:none;font-size:14px;transition:border-color .15s,box-shadow .15s;\n}\n.search-box input::placeholder{color:var(--faint)}\n.search-box input:focus{border-color:var(--yellow);box-shadow:0 0 0 3px rgba(255,203,5,.22)}\ninput[type=search]::-webkit-search-cancel-button{-webkit-appearance:none}\n\n.section-label{\n  font-size:11px;letter-spacing:1.1px;text-transform:uppercase;\n  color:var(--yellow);padding:4px 8px 0;font-weight:800;\n}\n.chat-list{flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:5px;margin:0 -4px;padding:0 4px}\n.chat-item{\n  display:flex;align-items:center;gap:9px;padding:10px;border-radius:var(--r-s);\n  color:var(--muted);font-size:14px;border:2px solid transparent;\n  transition:background .13s,color .13s,border-color .13s,transform .13s;\n}\n.chat-item:hover{background:var(--panel);color:var(--text);transform:translateX(2px)}\n.chat-item.active{\n  background:linear-gradient(135deg,rgba(61,139,255,.26),rgba(255,203,5,.16));\n  color:#fff;border-color:var(--yellow);\n}\n.chat-item .chat-ico{width:16px;height:16px;flex:none;color:var(--faint)}\n.chat-item.active .chat-ico{color:var(--yellow)}\n.chat-title{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left;font-weight:600}\n.chat-acts{display:flex;gap:2px;opacity:0;transition:opacity .13s}\n.chat-item:hover .chat-acts,.chat-item.active .chat-acts{opacity:1}\n.chat-acts button{\n  width:26px;height:26px;display:grid;place-items:center;border-radius:7px;color:var(--faint);\n  transition:background .12s,color .12s;\n}\n.chat-acts button:hover{background:rgba(255,255,255,.12);color:var(--text)}\n.chat-acts button.del:hover{background:rgba(255,77,77,.22);color:var(--red)}\n.chat-acts svg{width:14px;height:14px}\n.empty-history{color:var(--faint);font-size:13px;padding:14px 10px;text-align:center;line-height:1.6;white-space:pre-line}\n\n.sidebar-foot{display:flex;flex-direction:column;gap:2px;border-top:2px solid var(--line);padding-top:10px}\n.foot-btn{\n  display:flex;align-items:center;gap:10px;padding:10px;border-radius:var(--r-s);\n  color:var(--muted);font-size:14px;font-weight:600;transition:background .13s,color .13s;\n}\n.foot-btn:hover{background:var(--panel);color:var(--text)}\n.foot-btn.danger:hover{background:rgba(255,77,77,.16);color:var(--red)}\n\n.scrim{position:fixed;inset:0;background:rgba(3,7,20,.7);backdrop-filter:blur(3px);z-index:40}\n\n/* ══════════════ Main ══════════════ */\n.main{flex:1;display:flex;flex-direction:column;min-width:0;position:relative}\n\n.topbar{\n  position:relative;z-index:2;\n  display:flex;align-items:center;gap:12px;padding:11px 20px;\n  background:linear-gradient(180deg,var(--panel-2),var(--bg-2));\n  border-bottom:3px solid var(--yellow);\n  box-shadow:0 6px 18px rgba(0,0,0,.3);\n}\n.icon-btn{\n  width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:11px;\n  color:var(--muted);font-size:18px;border:2px solid transparent;\n  transition:background .13s,color .13s,border-color .13s;\n}\n.icon-btn:hover{background:var(--panel);color:var(--text);border-color:var(--line)}\n.menu-btn{display:none}\n.model-info{flex:1;min-width:0}\n.model-name{font-weight:800;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.model-status{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--muted);margin-top:2px;font-weight:600}\n.model-status .dot{\n  width:8px;height:8px;border-radius:99px;background:var(--green);flex:none;\n  box-shadow:0 0 0 3px rgba(61,220,132,.22);animation:pulse 2.2s ease-in-out infinite;\n}\n.model-status.busy .dot{background:var(--yellow);box-shadow:0 0 0 3px rgba(255,203,5,.22)}\n.model-status.err .dot{background:var(--red);box-shadow:0 0 0 3px rgba(255,77,77,.22);animation:none}\n@keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}\n\n.btn-model{\n  display:flex;align-items:center;gap:8px;flex:none;\n  padding:10px 16px;border-radius:999px;font-size:13.5px;font-weight:800;\n  background:var(--grad);color:#fff;border:2.5px solid var(--edge);\n  box-shadow:0 4px 0 var(--blue-deep);\n  transition:transform .12s,box-shadow .12s,filter .12s;\n}\n.btn-model:hover{filter:brightness(1.1);transform:translateY(-2px);box-shadow:0 6px 0 var(--blue-deep)}\n.btn-model:active{transform:translateY(3px);box-shadow:0 1px 0 var(--blue-deep)}\n.btn-model svg{width:15px;height:15px}\n\n/* ══════════════ Messages ══════════════ */\n.messages{position:relative;z-index:1;flex:1;overflow-y:auto;padding:26px 20px 12px;scroll-behavior:smooth}\n.thread{max-width:860px;margin:0 auto;display:flex;flex-direction:column;gap:22px}\n\n.msg{display:flex;gap:12px;align-items:flex-start;animation:rise .3s cubic-bezier(.2,.9,.3,1.15) both}\n@keyframes rise{from{opacity:0;transform:translateY(12px) scale(.98)}to{opacity:1;transform:none}}\n.msg.user{flex-direction:row-reverse}\n.avatar{\n  width:36px;height:36px;flex:none;border-radius:11px;display:grid;place-items:center;\n  font-size:12px;font-weight:800;margin-top:2px;border:2.5px solid var(--edge);\n}\n.msg.ai .avatar{background:var(--grad-warm);color:var(--ink);box-shadow:0 4px 0 var(--yellow-deep)}\n.msg.user .avatar{background:var(--grad);color:#fff;box-shadow:0 4px 0 var(--blue-deep)}\n.bubble-col{min-width:0;max-width:min(100%,680px);display:flex;flex-direction:column;gap:8px}\n.msg.user .bubble-col{align-items:flex-end}\n\n.bubble{\n  padding:14px 17px;border-radius:var(--r-l);font-size:15px;line-height:1.7;\n  word-wrap:break-word;overflow-wrap:anywhere;border:2.5px solid var(--edge);\n}\n.msg.user .bubble{\n  background:var(--grad);color:#fff;border-bottom-right-radius:7px;\n  box-shadow:0 5px 0 var(--blue-deep);white-space:pre-wrap;\n}\n.msg.ai .bubble{\n  background:var(--panel);border-bottom-left-radius:7px;\n  box-shadow:0 5px 0 var(--edge);border-left:5px solid var(--yellow);\n}\n.msg.ai .bubble.error{border-color:var(--edge);border-left-color:var(--red);background:var(--err-bg)}\n.msg.ai .bubble.error .err-title{color:var(--red);font-weight:800;display:block;margin-bottom:3px}\n\n.reasoning{\n  font-size:13.5px;color:var(--faint);border-left:3px solid var(--line);\n  padding:2px 0 2px 12px;margin-bottom:10px;white-space:pre-wrap;font-style:italic;\n}\n\n.msg-acts{display:flex;gap:4px;padding-left:3px;flex-wrap:wrap}\n.act{\n  display:flex;align-items:center;gap:5px;padding:6px 11px;border-radius:99px;\n  font-size:12.5px;font-weight:600;color:var(--muted);\n  background:var(--panel);border:2px solid var(--line);\n  transition:background .12s,color .12s,border-color .12s,transform .12s;\n}\n.act:hover{background:var(--panel-2);color:var(--text);border-color:var(--yellow);transform:translateY(-1px)}\n.act.on{color:var(--ink);background:var(--grad-warm);border-color:var(--edge)}\n.act.on.down{color:#fff;background:var(--grad-hot);border-color:var(--edge)}\n.act svg{width:14px;height:14px}\n\n.typing{display:inline-flex;align-items:center;gap:9px;color:var(--muted);font-size:14px;font-weight:600}\n.typing .dots{display:inline-flex;gap:5px}\n.typing .dots i{width:8px;height:8px;border-radius:99px;background:var(--yellow);animation:blink 1.35s infinite}\n.typing .dots i:nth-child(2){animation-delay:.18s;background:var(--blue)}\n.typing .dots i:nth-child(3){animation-delay:.36s;background:var(--red)}\n@keyframes blink{0%,60%,100%{opacity:.25;transform:translateY(0)}30%{opacity:1;transform:translateY(-5px)}}\n.caret{display:inline-block;width:8px;height:16px;vertical-align:-3px;margin-left:2px;background:var(--yellow);border-radius:2px;animation:caret 1s steps(2) infinite}\n@keyframes caret{0%,100%{opacity:1}50%{opacity:0}}\n\n/* ══════════════ Markdown ══════════════ */\n.md>*:first-child{margin-top:0}\n.md>*:last-child{margin-bottom:0}\n.md p{margin:0 0 11px}\n.md h1,.md h2,.md h3,.md h4{margin:18px 0 9px;line-height:1.3;font-weight:800}\n.md h1{font-size:1.4em}.md h2{font-size:1.24em}.md h3{font-size:1.12em}.md h4{font-size:1.02em}\n.md h1,.md h2{padding-bottom:6px;border-bottom:2px solid var(--line)}\n.md ul,.md ol{margin:0 0 11px;padding-left:22px}\n.md li{margin:5px 0}\n.md li::marker{color:var(--yellow);font-weight:800}\n.md a{color:var(--blue-2);text-decoration:none;border-bottom:2px solid rgba(111,176,255,.4);font-weight:600}\n.md a:hover{color:#a9ceff;border-bottom-color:#a9ceff}\n.md blockquote{margin:0 0 11px;padding:4px 0 4px 14px;border-left:4px solid var(--red);color:var(--muted)}\n.md hr{border:0;border-top:2px solid var(--line);margin:16px 0}\n.md strong{font-weight:800;color:var(--yellow-2)}\n.md code:not(pre code){\n  background:rgba(255,203,5,.16);border:1px solid rgba(255,203,5,.34);\n  padding:1.5px 6px;border-radius:6px;font-family:var(--mono);font-size:.875em;color:var(--yellow-2);\n}\n.md .table-wrap{overflow-x:auto;margin:0 0 12px;border:2.5px solid var(--edge);border-radius:var(--r-m)}\n.md table{border-collapse:collapse;width:100%;font-size:13.8px}\n.md th,.md td{padding:10px 13px;text-align:left;border-bottom:1px solid var(--line-soft)}\n.md th{background:var(--grad);color:#fff;font-weight:800;white-space:nowrap}\n.md tr:last-child td{border-bottom:0}\n.md tbody tr:nth-child(even){background:rgba(255,255,255,.035)}\n.md tbody tr:hover{background:rgba(255,203,5,.09)}\n\n.code-block{\n  margin:0 0 12px;border:2.5px solid var(--edge);border-radius:var(--r-m);\n  overflow:hidden;background:var(--code-bg);box-shadow:0 4px 0 rgba(0,0,0,.35);\n}\n.code-head{\n  display:flex;align-items:center;justify-content:space-between;gap:10px;\n  padding:7px 8px 7px 14px;background:var(--panel-2);border-bottom:2px solid var(--edge);\n}\n.code-lang{font-size:11.5px;letter-spacing:.9px;text-transform:uppercase;color:var(--yellow);font-weight:800}\n.code-copy{\n  display:flex;align-items:center;gap:6px;padding:5px 11px;border-radius:99px;\n  font-size:12px;font-weight:600;color:var(--muted);border:2px solid var(--line);\n  transition:background .12s,color .12s,border-color .12s;\n}\n.code-copy:hover{background:var(--raised);color:var(--text);border-color:var(--yellow)}\n.code-copy svg{width:13px;height:13px}\n.code-block pre{margin:0;padding:14px;overflow-x:auto}\n.code-block code{font-family:var(--mono);font-size:13.2px;line-height:1.62;white-space:pre}\n.tok-kw{color:#ff9ecb}.tok-str{color:#9fe8a0}.tok-num{color:var(--yellow-2)}\n.tok-com{color:#6a7fad;font-style:italic}.tok-fn{color:var(--blue-2)}.tok-op{color:#89ddff}\n\n/* ══════════════ Welcome + starter cards ══════════════ */\n.welcome{max-width:1120px;margin:0 auto;padding:40px 6px 24px;text-align:center;animation:rise .42s ease both}\n.welcome h1{\n  margin:0 0 10px;font-size:clamp(30px,6vw,46px);font-weight:900;letter-spacing:-.8px;\n  background:var(--grad-warm);-webkit-background-clip:text;background-clip:text;color:transparent;\n  filter:drop-shadow(0 3px 0 rgba(10,20,40,.55));\n}\n.welcome p{margin:0 0 26px;color:var(--muted);font-size:16px;font-weight:600}\n\n.starters{display:grid;grid-template-columns:repeat(auto-fit,minmax(158px,1fr));gap:12px;text-align:left}\n.starter{\n  position:relative;overflow:hidden;\n  display:flex;flex-direction:column;gap:9px;padding:16px 15px 14px;\n  border-radius:var(--r-l);border:3px solid var(--edge);color:var(--ink);\n  background:var(--card,linear-gradient(150deg,#dfe7f5,#b9c9e4));\n  box-shadow:0 6px 0 var(--card-deep,#7d8ba5),0 16px 28px rgba(0,0,0,.34);\n  transition:transform .15s cubic-bezier(.2,.9,.3,1.2),box-shadow .15s,filter .15s;\n}\n.starter:hover{transform:translateY(-5px) rotate(-.7deg);box-shadow:0 11px 0 var(--card-deep,#7d8ba5),0 22px 36px rgba(0,0,0,.42);filter:brightness(1.04)}\n.starter:active{transform:translateY(3px);box-shadow:0 2px 0 var(--card-deep,#7d8ba5)}\n.starter.chosen{outline:4px solid var(--yellow);outline-offset:3px}\n.starter .s-shine{\n  position:absolute;top:-70%;left:-35%;width:45%;height:240%;\n  background:linear-gradient(90deg,transparent,rgba(255,255,255,.5),transparent);\n  transform:rotate(18deg);transition:left .55s ease;pointer-events:none;\n}\n.starter:hover .s-shine{left:125%}\n.starter .s-icon{\n  font-size:28px;line-height:1;width:46px;height:46px;flex:none;\n  display:grid;place-items:center;border-radius:14px;\n  background:rgba(255,255,255,.6);border:2.5px solid rgba(10,20,40,.35);\n}\n.starter .s-body{display:flex;flex-direction:column;gap:2px;min-width:0}\n.starter .s-name{font-size:19px;font-weight:900;letter-spacing:-.3px}\n.starter .s-desc{font-size:13.5px;font-weight:600;opacity:.82}\n.starter .s-status{\n  display:inline-flex;align-items:center;gap:6px;align-self:flex-start;\n  padding:4px 11px;border-radius:99px;font-size:11.5px;font-weight:800;\n  letter-spacing:.4px;border:2px solid rgba(10,20,40,.4);\n}\n.starter .s-status i{width:8px;height:8px;border-radius:99px;flex:none}\n.starter .s-status.on{background:#0f7a44;color:#fff}\n.starter .s-status.on i{background:#5dffa8;box-shadow:0 0 0 3px rgba(93,255,168,.3);animation:pulse 2.2s ease-in-out infinite}\n.starter .s-status.off{background:#5d1414;color:#ffd7d7}\n.starter .s-status.off i{background:#ff8080}\n.starter .s-id{\n  font-family:var(--mono);font-size:10.5px;font-weight:600;opacity:.62;\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n}\n.starters-empty{color:var(--faint);font-size:13.5px;padding:18px;text-align:center;grid-column:1/-1}\n\n/* Card colours come from theme tokens - dark ink on bright cards keeps the\n   text readable in every theme. */\n.starter[data-type=electric]{--card:var(--c1);--card-deep:var(--c1d)}\n.starter[data-type=fire]    {--card:var(--c2);--card-deep:var(--c2d)}\n.starter[data-type=water]   {--card:var(--c3);--card-deep:var(--c3d)}\n.starter[data-type=grass]   {--card:var(--c4);--card-deep:var(--c4d)}\n.starter[data-type=deepseek]{--card:var(--c5);--card-deep:var(--c5d)}\n.starter[data-type=ollama]  {--card:var(--c6);--card-deep:var(--c6d)}\n\n.tag-opt{\n  font-size:10.5px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;\n  color:var(--faint);border:1.5px solid var(--line);border-radius:99px;padding:1px 7px;\n}\n\n/* theme picker in Settings */\n.themes{display:grid;grid-template-columns:repeat(auto-fit,minmax(102px,1fr));gap:8px}\n.themes button{\n  display:flex;flex-direction:column;gap:7px;padding:9px;border-radius:var(--r-m);\n  background:var(--panel);border:2.5px solid var(--line);\n  font-size:12.5px;font-weight:700;color:var(--muted);\n  transition:border-color .14s,transform .14s,color .14s,box-shadow .14s;\n}\n.themes button:hover{border-color:var(--yellow);color:var(--text);transform:translateY(-2px)}\n.themes button.active{border-color:var(--yellow);color:var(--text);box-shadow:0 3px 0 var(--yellow-deep)}\n.t-swatch{height:26px;border-radius:calc(var(--r-s) - 3px);border:2px solid rgba(0,0,0,.45)}\n.themes button[data-t=pokemon]   .t-swatch{background:linear-gradient(90deg,#ffcb05,#3d8bff,#ff4d4d)}\n.themes button[data-t=anime]     .t-swatch{background:linear-gradient(90deg,#ff6bb5,#7c6bff,#5ee7c5)}\n.themes button[data-t=minecraft] .t-swatch{background:linear-gradient(90deg,#7cb342,#8b5a2b,#3ec5cf)}\n.themes button[data-t=roblox]    .t-swatch{background:linear-gradient(90deg,#e2231a,#ffffff,#00a2ff)}\n.themes button[data-t=gta]       .t-swatch{background:linear-gradient(90deg,#9dcd42,#e8a33d,#4fa3d9)}\n\n.quick-label{\n  margin:30px 0 12px;font-size:11.5px;letter-spacing:1.1px;text-transform:uppercase;\n  color:var(--faint);font-weight:800;\n}\n.quick{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.quick button{\n  display:flex;align-items:center;gap:12px;padding:15px;border-radius:var(--r-m);\n  background:var(--panel);border:2.5px solid var(--line);text-align:left;\n  font-size:14.5px;font-weight:600;color:var(--text);\n  box-shadow:0 4px 0 var(--edge);\n  transition:border-color .15s,transform .15s,background .15s,box-shadow .15s;\n}\n.quick button:hover{border-color:var(--yellow);transform:translateY(-3px);background:var(--panel-2);box-shadow:0 7px 0 var(--edge)}\n.quick button:active{transform:translateY(2px);box-shadow:0 1px 0 var(--edge)}\n.quick .emoji{font-size:22px;flex:none}\n\n/* ══════════════ Composer ══════════════ */\n.composer-wrap{position:relative;z-index:2;padding:8px 20px 16px}\n.composer{\n  max-width:860px;margin:0 auto;display:flex;align-items:flex-end;gap:8px;\n  padding:8px 8px 8px 17px;border-radius:var(--r-xl);\n  background:var(--panel);border:3px solid var(--line);\n  box-shadow:0 5px 0 var(--edge);\n  transition:border-color .15s,box-shadow .15s;\n}\n.composer:focus-within{border-color:var(--yellow);box-shadow:0 5px 0 var(--edge),0 0 0 4px rgba(255,203,5,.2)}\n.composer textarea{\n  flex:1;border:0;outline:none;background:none;resize:none;\n  font-size:15px;line-height:1.55;padding:9px 0;max-height:210px;min-height:22px;color:var(--text);\n}\n.composer textarea::placeholder{color:var(--faint)}\n.btn-send{\n  width:44px;height:44px;flex:none;border-radius:50%;display:grid;place-items:center;\n  background:var(--grad-hot);color:#fff;border:2.5px solid var(--edge);\n  box-shadow:0 4px 0 var(--red-deep);\n  transition:opacity .15s,transform .15s,filter .15s,box-shadow .15s;\n}\n.btn-send svg{stroke:none;fill:currentColor;width:19px;height:19px;margin-left:2px}\n.btn-send:disabled{opacity:.35;cursor:not-allowed;box-shadow:0 4px 0 rgba(0,0,0,.3)}\n.btn-send:not(:disabled):hover{transform:translateY(-2px) scale(1.04);filter:brightness(1.08);box-shadow:0 6px 0 var(--red-deep)}\n.btn-send:not(:disabled):active{transform:translateY(3px);box-shadow:0 1px 0 var(--red-deep)}\n.btn-stop{\n  display:flex;align-items:center;gap:8px;margin:12px auto 0;\n  padding:9px 18px;border-radius:999px;font-size:13.5px;font-weight:800;\n  background:var(--panel);border:2.5px solid var(--red);color:var(--red);\n  box-shadow:0 4px 0 var(--edge);\n  transition:background .14s,color .14s,transform .12s,box-shadow .12s;\n}\n.btn-stop:hover{background:var(--grad-hot);color:#fff;border-color:var(--edge)}\n.btn-stop:active{transform:translateY(3px);box-shadow:0 1px 0 var(--edge)}\n.stop-square{width:10px;height:10px;border-radius:2px;background:currentColor}\n.composer-hint{text-align:center;color:var(--faint);font-size:11.5px;margin-top:9px;font-weight:600}\n.composer-hint kbd{\n  font-family:var(--font);background:var(--panel-2);border:2px solid var(--line);\n  border-radius:6px;padding:1px 6px;font-size:11px;font-weight:700;\n}\n\n/* ══════════════ Modals ══════════════ */\n.modal{\n  position:fixed;inset:0;z-index:60;display:grid;place-items:center;padding:18px;\n  background:rgba(3,7,20,.74);backdrop-filter:blur(5px);animation:fade .17s ease both;\n}\n@keyframes fade{from{opacity:0}to{opacity:1}}\n.modal-card{\n  width:100%;max-width:580px;max-height:min(88dvh,800px);display:flex;flex-direction:column;\n  background:var(--bg-2);border:3px solid var(--line);border-radius:var(--r-xl);\n  box-shadow:var(--shadow),0 0 0 4px rgba(255,203,5,.14);\n  animation:pop .24s cubic-bezier(.2,.9,.3,1.25) both;overflow:hidden;\n}\n@keyframes pop{from{opacity:0;transform:translateY(18px) scale(.96)}to{opacity:1;transform:none}}\n.modal-wide{max-width:940px}\n.modal-narrow{max-width:430px}\n.modal-head{\n  display:flex;align-items:center;justify-content:space-between;gap:12px;\n  padding:15px 18px;border-bottom:3px solid var(--yellow);flex:none;\n  background:linear-gradient(180deg,var(--panel-2),var(--panel));\n}\n.modal-head h2{margin:0;font-size:18px;font-weight:900}\n.modal-body{padding:18px;overflow-y:auto}\n.modal-foot{\n  display:flex;align-items:center;justify-content:flex-end;gap:10px;\n  padding:14px 18px;border-top:2px solid var(--line);flex:none;\n}\n.modal-search{position:relative;display:flex;align-items:center;padding:14px 18px 0;flex:none}\n.modal-search .search-icon{position:absolute;left:31px;width:16px;height:16px;color:var(--faint)}\n.modal-search input{\n  width:100%;padding:11px 14px 11px 37px;border-radius:var(--r-m);\n  background:var(--panel);border:2px solid var(--line);outline:none;font-size:14px;color:var(--text);\n}\n.modal-search input:focus{border-color:var(--yellow);box-shadow:0 0 0 3px rgba(255,203,5,.2)}\n\n.picker-featured{padding:16px 18px 0;flex:none}\n.picker-featured-label{\n  font-size:11px;letter-spacing:1.1px;text-transform:uppercase;\n  color:var(--yellow);font-weight:800;margin-bottom:10px;\n}\n.starters-compact{grid-template-columns:repeat(auto-fit,minmax(168px,1fr));gap:10px}\n.starters-compact .starter{padding:12px 12px 11px;gap:7px;border-radius:var(--r-m)}\n.starters-compact .s-icon{width:36px;height:36px;font-size:21px;border-radius:11px}\n.starters-compact .s-name{font-size:16px}\n.starters-compact .s-desc{font-size:12px}\n.starters-compact .s-id{display:none}\n\n.picker{display:flex;min-height:0;flex:1;padding:16px 18px 0;gap:14px}\n.picker-cats{\n  width:176px;flex:none;display:flex;flex-direction:column;gap:4px;overflow-y:auto;\n  border-right:2px solid var(--line);padding-right:10px;\n}\n.picker-cats button{\n  display:flex;align-items:center;gap:9px;padding:9px 11px;border-radius:var(--r-s);\n  font-size:13.8px;font-weight:600;color:var(--muted);text-align:left;\n  border:2px solid transparent;transition:background .12s,color .12s,border-color .12s;\n}\n.picker-cats button:hover{background:var(--panel);color:var(--text)}\n.picker-cats button.active{background:var(--grad);color:#fff;border-color:var(--edge)}\n.picker-cats .count{margin-left:auto;font-size:11px;opacity:.8;font-weight:700}\n.picker-models{flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:9px;padding-right:2px}\n.model-card{\n  display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:var(--r-m);\n  background:var(--panel);border:2.5px solid var(--line);text-align:left;width:100%;\n  box-shadow:0 3px 0 var(--edge);\n  transition:border-color .14s,background .14s,transform .14s,box-shadow .14s;\n}\n.model-card:hover{border-color:var(--yellow);background:var(--panel-2);transform:translateX(4px);box-shadow:0 5px 0 var(--edge)}\n.model-card.active{border-color:var(--yellow);background:linear-gradient(135deg,rgba(61,139,255,.3),rgba(255,203,5,.18))}\n.model-card .mc-body{flex:1;min-width:0}\n.model-card .mc-name{font-weight:800;font-size:14.5px;margin-bottom:3px}\n.model-card .mc-id{\n  font-family:var(--mono);font-size:11.5px;color:var(--faint);\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n}\n.model-card .mc-desc{font-size:12.5px;color:var(--muted);margin-top:4px}\n.model-card .mc-check{color:var(--yellow);flex:none;opacity:0}\n.model-card.active .mc-check{opacity:1}\n.model-card .mc-del{color:var(--faint);flex:none;width:28px;height:28px;border-radius:7px;display:grid;place-items:center}\n.model-card .mc-del:hover{background:rgba(255,77,77,.2);color:var(--red)}\n.picker-empty{color:var(--faint);text-align:center;padding:36px 12px;font-size:14px}\n.custom-model{flex-direction:column;align-items:stretch;gap:8px}\n.custom-model label{font-size:12.5px;color:var(--muted);font-weight:600}\n.custom-row{display:flex;gap:8px}\n.custom-row input{\n  flex:1;padding:11px 13px;border-radius:var(--r-m);background:var(--panel);\n  border:2px solid var(--line);outline:none;font-family:var(--mono);font-size:13px;color:var(--text);\n}\n.custom-row input:focus{border-color:var(--yellow);box-shadow:0 0 0 3px rgba(255,203,5,.2)}\n\n.field{margin-bottom:20px}\n.field:last-child{margin-bottom:0}\n.field label{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:13.5px;font-weight:800;margin-bottom:9px}\n.field output{\n  font-family:var(--mono);font-size:12.5px;color:var(--ink);font-weight:700;\n  background:var(--grad-warm);padding:3px 10px;border-radius:99px;border:2px solid var(--edge);\n}\n.field textarea,.field input[type=text],.field input[type=password]{\n  width:100%;padding:11px 13px;border-radius:var(--r-m);background:var(--panel);\n  border:2px solid var(--line);outline:none;font-size:14px;resize:vertical;line-height:1.55;color:var(--text);\n}\n.field textarea:focus,.field input[type=text]:focus,.field input[type=password]:focus{border-color:var(--yellow);box-shadow:0 0 0 3px rgba(255,203,5,.2)}\n.field .hint{margin:7px 0 0;font-size:12px;color:var(--faint)}\ninput[type=range]{\n  -webkit-appearance:none;appearance:none;width:100%;height:9px;border-radius:99px;\n  background:linear-gradient(90deg,var(--blue),var(--yellow),var(--red));\n  outline:none;border:2px solid var(--edge);\n}\ninput[type=range]::-webkit-slider-thumb{\n  -webkit-appearance:none;appearance:none;width:22px;height:22px;border-radius:50%;\n  background:#fff;border:3px solid var(--edge);box-shadow:0 2px 6px rgba(0,0,0,.5);cursor:pointer;\n}\ninput[type=range]::-moz-range-thumb{\n  width:22px;height:22px;border:3px solid var(--edge);border-radius:50%;background:#fff;\n  box-shadow:0 2px 6px rgba(0,0,0,.5);cursor:pointer;\n}\n.btn-primary{\n  padding:11px 22px;border-radius:var(--r-m);font-weight:800;font-size:14px;\n  background:var(--grad-warm);color:var(--ink);border:2.5px solid var(--edge);\n  box-shadow:0 4px 0 var(--yellow-deep);\n  transition:filter .14s,transform .12s,box-shadow .12s;\n}\n.btn-primary:hover{filter:brightness(1.06);transform:translateY(-2px);box-shadow:0 6px 0 var(--yellow-deep)}\n.btn-primary:active{transform:translateY(3px);box-shadow:0 1px 0 var(--yellow-deep)}\n.btn-ghost{\n  padding:11px 18px;border-radius:var(--r-m);font-size:14px;font-weight:700;color:var(--muted);\n  border:2.5px solid var(--line);transition:background .13s,color .13s,border-color .13s;\n}\n.btn-ghost:hover{background:var(--panel);color:var(--text);border-color:var(--muted)}\n\n/* ══════════════ Toasts ══════════════ */\n.toasts{position:fixed;top:78px;right:16px;z-index:90;display:flex;flex-direction:column;gap:10px;max-width:min(400px,calc(100vw - 32px))}\n.toast{\n  display:flex;align-items:flex-start;gap:11px;padding:13px 15px;border-radius:var(--r-m);\n  background:var(--panel-2);border:2.5px solid var(--line);box-shadow:var(--shadow);\n  font-size:13.8px;line-height:1.5;animation:slidein .28s cubic-bezier(.2,.9,.3,1.25) both;\n}\n@keyframes slidein{from{opacity:0;transform:translateX(30px)}to{opacity:1;transform:none}}\n.toast.out{animation:slideout .22s ease both}\n@keyframes slideout{to{opacity:0;transform:translateX(30px)}}\n.toast .ico{flex:none;width:19px;height:19px;margin-top:1px}\n.toast.err{border-color:var(--red)}\n.toast.err .ico{color:var(--red)}\n.toast.ok{border-color:var(--green)}\n.toast.ok .ico{color:var(--green)}\n.toast.info{border-color:var(--blue)}\n.toast.info .ico{color:var(--blue)}\n.toast .t-body{flex:1;min-width:0}\n.toast .t-title{font-weight:800;margin-bottom:2px}\n.toast .t-text{color:var(--muted);overflow-wrap:anywhere}\n.toast .t-close{color:var(--faint);flex:none;width:22px;height:22px;border-radius:6px;display:grid;place-items:center}\n.toast .t-close:hover{background:rgba(255,255,255,.12);color:var(--text)}\n\n/* ══════════════ Responsive ══════════════ */\n@media (max-width:900px){\n  .picker{flex-direction:column;gap:10px;overflow-y:auto}\n  .picker-cats{\n    width:100%;flex-direction:row;overflow-x:auto;border-right:0;\n    border-bottom:2px solid var(--line);padding:0 0 10px;gap:6px;\n  }\n  .picker-cats button{white-space:nowrap;flex:none}\n  .picker-cats .count{display:none}\n  .picker-models{overflow:visible}\n}\n@media (max-width:820px){\n  .sidebar{\n    position:fixed;top:0;bottom:0;left:0;z-index:50;\n    transform:translateX(-102%);transition:transform .28s cubic-bezier(.3,.9,.3,1);\n    box-shadow:var(--shadow);\n  }\n  .sidebar.open{transform:none}\n  .sidebar .sidebar-close{display:grid}\n  .menu-btn{display:grid}\n  .topbar{padding:9px 12px}\n  .messages{padding:18px 12px 8px}\n  .composer-wrap{padding:6px 12px 12px}\n  .bubble-col{max-width:calc(100% - 48px)}\n  .welcome{padding:26px 4px 16px}\n  .starters{grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}\n  .starter{padding:13px 12px 12px}\n  .starter .s-icon{width:38px;height:38px;font-size:22px}\n  .starter .s-name{font-size:17px}\n  .starter .s-id{display:none}\n  .quick{grid-template-columns:1fr}\n  .toasts{top:auto;bottom:16px;left:12px;right:12px;max-width:none}\n  .btn-model span{display:none}\n  .btn-model{padding:10px 13px}\n  .composer-hint{display:none}\n  .pokeball-bg{width:280px;height:280px;top:-90px;right:-90px}\n}\n@media (max-width:420px){\n  .avatar{width:30px;height:30px;font-size:11px}\n  .bubble{font-size:14.5px;padding:12px 14px}\n  .model-name{font-size:14.5px}\n  .modal{padding:0}\n  .modal-card{max-width:none;max-height:100dvh;height:100dvh;border-radius:0;border:0}\n  .welcome h1{font-size:28px}\n  .starters{gap:9px}\n  .starter .s-desc{font-size:11.5px}\n}\n@media (prefers-reduced-motion:reduce){\n  *{animation-duration:.01ms!important;transition-duration:.01ms!important}\n  .messages{scroll-behavior:auto}\n}\n\n/* ══════════════════════════════════════════════════════════════\n   Themes\n   Every surface reads from the tokens above, so a theme is mostly a\n   new palette. Each block also adjusts the corner radius, the logo\n   mark and, where it fits, the typeface.\n   ══════════════════════════════════════════════════════════════ */\n\n/* ────────── Аниме: неон, розовый и фиолет ────────── */\n:root[data-theme=anime]{\n  --bg:#150b22; --bg-2:#1d0f2e; --panel:#291540; --panel-2:#351c53;\n  --raised:#452470; --line:#4d2c78; --line-soft:#3a2160;\n  --text:#ffffff; --muted:#e0c9f7; --faint:#a98ecb;\n\n  --yellow:#ff6bb5; --yellow-2:#ffa8d6; --yellow-deep:#c22a7c;\n  --blue:#8b7bff; --blue-2:#b9adff; --blue-deep:#5436d6;\n  --red:#ff5c8a; --red-2:#ff92b2; --red-deep:#c2185b;\n  --green:#5ee7c5; --green-deep:#18a886;\n  --ink:#2c0f42;\n  --edge:#1a0a28; --code-bg:#190a26; --err-bg:#3a0f2e;\n\n  --c1:linear-gradient(150deg,#ffd6ec,#ff6bb5 60%,#e0348c); --c1d:#9c1a5e;\n  --c2:linear-gradient(150deg,#e2d4ff,#8b7bff 58%,#6247e8); --c2d:#3c2aa8;\n  --c3:linear-gradient(150deg,#cdf6ff,#5ed7ff 58%,#23a8e0); --c3d:#0f6f96;\n  --c4:linear-gradient(150deg,#d2fff1,#5ee7c5 58%,#22bfa0); --c4d:#0d7d68;\n  --c5:linear-gradient(150deg,#e8d0ff,#a06bff 58%,#7c3ce0); --c5d:#4d1c93;\n  --c6:linear-gradient(150deg,#ffe6f5,#ffb3dd 58%,#f07ec2); --c6d:#a8377e;\n\n  --r-s:14px; --r-m:18px; --r-l:24px; --r-xl:30px;\n}\n:root[data-theme=anime] body::before{\n  background:\n    radial-gradient(900px 520px at 10% -10%,rgba(255,107,181,.20),transparent 60%),\n    radial-gradient(820px 480px at 92% 0%,rgba(139,123,255,.22),transparent 62%),\n    radial-gradient(760px 520px at 55% 112%,rgba(94,231,197,.14),transparent 62%),\n    radial-gradient(circle at 50% 50%,rgba(255,255,255,.05) 1.5px,transparent 1.6px) 0 0/30px 30px;\n}\n:root[data-theme=anime] .brand-mark,\n:root[data-theme=anime] .welcome-logo{\n  background:radial-gradient(circle at 34% 28%,#ffe3f3,#ff6bb5 46%,#8b7bff);\n  border-color:#2c0f42;\n  box-shadow:0 5px 0 rgba(0,0,0,.3),0 0 26px rgba(255,107,181,.5);\n}\n:root[data-theme=anime] .brand-mark::after,\n:root[data-theme=anime] .welcome-logo::after{\n  width:34%;height:34%;border-radius:3px;background:#fff;border-color:#2c0f42;\n  transform:translate(-50%,-50%) rotate(45deg);\n}\n\n/* ────────── Minecraft: блоки, трава и земля ────────── */\n:root[data-theme=minecraft]{\n  --bg:#14110d; --bg-2:#1c1813; --panel:#2a241c; --panel-2:#372f24;\n  --raised:#463a2c; --line:#544634; --line-soft:#3f3527;\n  --text:#ffffff; --muted:#d3c7b0; --faint:#9c8f79;\n\n  --yellow:#7cb342; --yellow-2:#a5d66b; --yellow-deep:#4a7223;\n  --blue:#3ec5cf; --blue-2:#82e2ea; --blue-deep:#1c7a82;\n  --red:#c94b3b; --red-2:#e27764; --red-deep:#8a2e20;\n  --green:#7cb342; --green-deep:#4a7223;\n  --ink:#191309;\n  --edge:#0f0d09; --code-bg:#0d0b07; --err-bg:#2e1512;\n\n  --c1:linear-gradient(150deg,#a5d66b,#7cb342 58%,#5a8a2c); --c1d:#3c5e1b;\n  --c2:linear-gradient(150deg,#d8a06a,#8b5a2b 58%,#6b431f); --c2d:#432a12;\n  --c3:linear-gradient(150deg,#b6f0f5,#3ec5cf 58%,#219aa5); --c3d:#14646b;\n  --c4:linear-gradient(150deg,#b9b9b9,#7f7f7f 58%,#5c5c5c); --c4d:#3a3a3a;\n  --c5:linear-gradient(150deg,#cfd6e8,#6b7fa8 58%,#4b5c80); --c5d:#2d3850;\n  --c6:linear-gradient(150deg,#e4e4e4,#b0b0b0 58%,#8a8a8a); --c6d:#575757;\n\n  --r-s:0px; --r-m:0px; --r-l:0px; --r-xl:0px;\n  --font:ui-monospace,\"Courier New\",Courier,monospace;\n}\n:root[data-theme=minecraft] body::before{\n  background:\n    radial-gradient(900px 520px at 10% -10%,rgba(124,179,66,.16),transparent 60%),\n    radial-gradient(820px 480px at 92% 0%,rgba(139,90,43,.20),transparent 62%),\n    radial-gradient(circle at 50% 50%,rgba(255,255,255,.03) 2px,transparent 2.1px) 0 0/28px 28px;\n}\n:root[data-theme=minecraft] .brand-mark,\n:root[data-theme=minecraft] .welcome-logo{\n  border-radius:0;\n  background:linear-gradient(#7cb342 0 34%,#5a8a2c 34% 40%,#8b5a2b 40% 100%);\n  border-color:#14110d;\n}\n:root[data-theme=minecraft] .brand-mark::after,\n:root[data-theme=minecraft] .welcome-logo::after{\n  width:24%;height:24%;border-radius:0;top:64%;left:36%;\n  background:#6b431f;border-color:#14110d;box-shadow:none;\n}\n:root[data-theme=minecraft] .pokeball-bg{border-radius:0;animation:none;opacity:.02}\n:root[data-theme=minecraft] .starter,\n:root[data-theme=minecraft] .quick button,\n:root[data-theme=minecraft] .model-card{image-rendering:pixelated}\n\n/* ────────── Roblox: красный, белый, графит ────────── */\n:root[data-theme=roblox]{\n  --bg:#141618; --bg-2:#1b1e21; --panel:#24282c; --panel-2:#2f343a;\n  --raised:#3b4149; --line:#454c55; --line-soft:#373d45;\n  --text:#ffffff; --muted:#c6cdd6; --faint:#8d96a1;\n\n  --yellow:#e2231a; --yellow-2:#ff6a5e; --yellow-deep:#95100a;\n  --blue:#00a2ff; --blue-2:#66c8ff; --blue-deep:#00669e;\n  --red:#ff3b30; --red-2:#ff7d75; --red-deep:#a81f16;\n  --green:#00b06f; --green-deep:#007147;\n  --ink:#16191c;\n  --edge:#0d0f11; --code-bg:#0c0e10; --err-bg:#2e1210;\n\n  --c1:linear-gradient(150deg,#ff8b82,#e2231a 58%,#b0140d); --c1d:#7a0d08;\n  --c2:linear-gradient(150deg,#ffffff,#d7dde5 58%,#aeb7c2); --c2d:#78818d;\n  --c3:linear-gradient(150deg,#9ad9ff,#00a2ff 58%,#0077bd); --c3d:#004b78;\n  --c4:linear-gradient(150deg,#8ce8c2,#00b06f 58%,#008554); --c4d:#005637;\n  --c5:linear-gradient(150deg,#d5c4ff,#8b6cff 58%,#6244cc); --c5d:#3d2a85;\n  --c6:linear-gradient(150deg,#fff1cc,#ffc94d 58%,#e0a516); --c6d:#8f6708;\n\n  --r-s:8px; --r-m:12px; --r-l:16px; --r-xl:20px;\n}\n:root[data-theme=roblox] body::before{\n  background:\n    radial-gradient(900px 520px at 10% -10%,rgba(226,35,26,.18),transparent 60%),\n    radial-gradient(820px 480px at 92% 0%,rgba(0,162,255,.16),transparent 62%),\n    radial-gradient(circle at 50% 50%,rgba(255,255,255,.04) 1.4px,transparent 1.5px) 0 0/32px 32px;\n}\n:root[data-theme=roblox] .brand-mark,\n:root[data-theme=roblox] .welcome-logo{\n  border-radius:22%;\n  background:linear-gradient(135deg,#ff6a5e,#e2231a 58%,#95100a);\n  border-color:#141618;\n  transform:rotate(-8deg);\n}\n:root[data-theme=roblox] .brand-mark::after,\n:root[data-theme=roblox] .welcome-logo::after{\n  width:34%;height:34%;border-radius:14%;background:#fff;border-color:#141618;\n  transform:translate(-50%,-50%) rotate(14deg);\n}\n\n/* ────────── GTA San Andreas: зелёный и оранжевый ────────── */\n:root[data-theme=gta]{\n  --bg:#0e120c; --bg-2:#141a10; --panel:#1f2818; --panel-2:#2b3720;\n  --raised:#3a4a29; --line:#465831; --line-soft:#374526;\n  --text:#ffffff; --muted:#cfdcbb; --faint:#95a881;\n\n  --yellow:#9dcd42; --yellow-2:#c6e87f; --yellow-deep:#5d8a1c;\n  --blue:#4fa3d9; --blue-2:#8fc9ea; --blue-deep:#256489;\n  --red:#d84b2a; --red-2:#ee8058; --red-deep:#8d2c13;\n  --green:#9dcd42; --green-deep:#5d8a1c;\n  --ink:#131a08;\n  --edge:#080b06; --code-bg:#070a05; --err-bg:#2c1409;\n\n  --c1:linear-gradient(150deg,#d9ef9d,#9dcd42 58%,#74a127); --c1d:#4c6c15;\n  --c2:linear-gradient(150deg,#ffd79a,#e8a33d 58%,#c07c1c); --c2d:#84520c;\n  --c3:linear-gradient(150deg,#b6dcf2,#4fa3d9 58%,#2d7aa9); --c3d:#1b4e6e;\n  --c4:linear-gradient(150deg,#f0a58c,#d84b2a 58%,#ab3218); --c4d:#72200e;\n  --c5:linear-gradient(150deg,#cfe0ea,#6e93a8 58%,#4b6c80); --c5d:#2d4250;\n  --c6:linear-gradient(150deg,#e9e2cf,#bfb391 58%,#9a8d68); --c6d:#5f5740;\n\n  --r-s:4px; --r-m:7px; --r-l:11px; --r-xl:15px;\n}\n:root[data-theme=gta] body::before{\n  background:\n    radial-gradient(900px 520px at 10% -10%,rgba(157,205,66,.18),transparent 60%),\n    radial-gradient(820px 480px at 92% 0%,rgba(232,163,61,.18),transparent 62%),\n    radial-gradient(760px 520px at 55% 112%,rgba(79,163,217,.12),transparent 62%),\n    radial-gradient(circle at 50% 50%,rgba(255,255,255,.035) 1.4px,transparent 1.5px) 0 0/36px 36px;\n}\n:root[data-theme=gta] .brand-mark,\n:root[data-theme=gta] .welcome-logo{\n  background:conic-gradient(from 210deg,#9dcd42,#5d8a1c 38%,#e8a33d 68%,#9dcd42);\n  border-color:#0e120c;\n}\n:root[data-theme=gta] .brand-mark::after,\n:root[data-theme=gta] .welcome-logo::after{\n  width:42%;height:42%;background:#141a10;border-color:#9dcd42;box-shadow:none;\n}\n", "app.js": "/* ==============================================================\n   Multi AI Chat - frontend\n   The Hugging Face token lives on the server only. This file never\n   sees it: every completion goes through POST /api/chat.\n   ============================================================== */\n'use strict';\n\nconst $  = (id) => document.getElementById(id);\nconst el = (tag, cls, text) => {\n  const n = document.createElement(tag);\n  if (cls) n.className = cls;\n  if (text != null) n.textContent = text;\n  return n;\n};\nconst esc = (s) => String(s)\n  .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;')\n  .replace(/\"/g, '&quot;').replace(/'/g, '&#39;');\nconst uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);\n\n/* ============== Storage ============== */\nconst LS = {\n  chats:    'mac.chats',\n  current:  'mac.current',\n  settings: 'mac.settings',\n  model:    'mac.model',\n  custom:   'mac.customModels',\n};\n\nconst THEMES = [\n  { id: 'pokemon',   name: 'Pokémon' },\n  { id: 'anime',     name: 'Аниме' },\n  { id: 'minecraft', name: 'Minecraft' },\n  { id: 'roblox',    name: 'Roblox' },\n  { id: 'gta',       name: 'GTA SA' },\n];\n\nconst DEFAULT_SETTINGS = {\n  theme: 'pokemon',\n  systemPrompt: 'Ты — полезный ИИ-ассистент. Отвечай понятно, по существу и на языке пользователя. Оформляй код в Markdown-блоках.',\n  temperature: 0.7,\n  maxTokens: 2048,\n  topP: 0.95,\n};\n\nfunction load(key, fallback) {\n  try {\n    const raw = localStorage.getItem(key);\n    return raw == null ? fallback : JSON.parse(raw);\n  } catch { return fallback; }\n}\nfunction save(key, value) {\n  try { localStorage.setItem(key, JSON.stringify(value)); }\n  catch { toast('err', 'Хранилище переполнено', 'Не удалось сохранить историю. Удалите старые чаты.'); }\n}\n\n/* ============== State ============== */\nconst state = {\n  chats: load(LS.chats, []),\n  currentId: load(LS.current, null),\n  settings: Object.assign({}, DEFAULT_SETTINGS, load(LS.settings, {})),\n  catalog: { default: 'deepseek-ai/DeepSeek-V3-0324', categories: [] },\n  featured: [],\n  customModels: load(LS.custom, []),\n  model: load(LS.model, null),\n  activeCat: 'all',\n  filter: '',\n  modelFilter: '',\n  abort: null,\n  renameTarget: null,\n};\n\nfunction applyTheme(id) {\n  const known = THEMES.some((t) => t.id === id) ? id : 'pokemon';\n  document.documentElement.dataset.theme = known;\n}\napplyTheme(state.settings.theme);\n\nconst currentChat = () => state.chats.find((c) => c.id === state.currentId) || null;\nconst persistChats = () => { save(LS.chats, state.chats); save(LS.current, state.currentId); };\n\n/* ============== Toasts ============== */\nconst TOAST_ICONS = {\n  err:  '<path d=\"M12 8v5M12 16.5v.5\"/><circle cx=\"12\" cy=\"12\" r=\"9\"/>',\n  ok:   '<path d=\"M20 6L9 17l-5-5\"/>',\n  info: '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 11v5M12 7.5v.5\"/>',\n};\nfunction toast(kind, title, text, ms = 6000) {\n  const box = $('toasts');\n  if (!box) return;\n  const t = el('div', `toast ${kind}`);\n  t.innerHTML =\n    `<svg class=\"ico\" viewBox=\"0 0 24 24\">${TOAST_ICONS[kind] || TOAST_ICONS.info}<\/svg>` +\n    '<div class=\"t-body\"><div class=\"t-title\"><\/div><div class=\"t-text\"><\/div><\/div>' +\n    '<button class=\"t-close\" aria-label=\"Закрыть\">&#10005;<\/button>';\n  t.querySelector('.t-title').textContent = title;\n  t.querySelector('.t-text').textContent = text || '';\n  const close = () => { t.classList.add('out'); setTimeout(() => t.remove(), 220); };\n  t.querySelector('.t-close').onclick = close;\n  box.appendChild(t);\n  if (ms) setTimeout(close, ms);\n}\n\nasync function copyText(text, okMsg = 'Скопировано') {\n  try {\n    if (navigator.clipboard && window.isSecureContext) {\n      await navigator.clipboard.writeText(text);\n    } else {\n      const ta = el('textarea');\n      ta.value = text;\n      ta.style.cssText = 'position:fixed;opacity:0;pointer-events:none';\n      document.body.appendChild(ta); ta.select();\n      document.execCommand('copy'); ta.remove();\n    }\n    toast('ok', okMsg, '', 1800);\n    return true;\n  } catch {\n    toast('err', 'Не удалось скопировать', 'Браузер заблокировал доступ к буферу обмена.');\n    return false;\n  }\n}\n\n/* ==============================================================\n   Markdown renderer (self-contained - no external libraries)\n   ============================================================== */\nconst KEYWORDS = {\n  common: 'if else for while return function class const let var new this import from export default async await try catch finally throw switch case break continue typeof instanceof in of do yield static extends super null true false undefined',\n  python: 'def class return if elif else for while import from as try except finally raise with lambda yield pass break continue global nonlocal assert del is not and or in None True False self async await match case',\n  go: 'func package import return if else for range var const type struct interface map chan go defer select switch case break continue nil true false',\n  rust: 'fn let mut const struct enum impl trait pub use mod match if else for while loop return break continue self Self where as dyn ref move async await true false Some None Ok Err',\n  java: 'public private protected class interface extends implements static final void return if else for while new this super try catch finally throw throws import package int long double float boolean char String true false null',\n  sql: 'select from where join inner left right outer on group by order having limit offset insert into values update set delete create table alter drop index as and or not null distinct count sum avg min max case when then end',\n  css: 'important media supports keyframes import charset font-face root',\n  bash: 'if then else elif fi for while do done case esac function return echo export local read source cd exit',\n};\nconst LANG_ALIAS = {\n  js: 'common', javascript: 'common', ts: 'common', typescript: 'common',\n  jsx: 'common', tsx: 'common', json: 'common', c: 'java', cpp: 'java',\n  'c++': 'java', cs: 'java', csharp: 'java', kotlin: 'java', swift: 'java',\n  php: 'common', ruby: 'python', rb: 'python', py: 'python', sh: 'bash',\n  shell: 'bash', zsh: 'bash', yaml: 'python', yml: 'python', html: 'css', xml: 'css',\n};\nconst HASH_COMMENT = new Set(['python', 'py', 'bash', 'sh', 'shell', 'zsh', 'yaml', 'yml', 'ruby', 'rb', 'toml', 'ini', 'r', 'perl']);\nconst DASH_COMMENT = new Set(['sql', 'lua', 'haskell', 'hs', 'ada']);\n\nfunction highlight(code, lang) {\n  const key = (lang || '').toLowerCase();\n  const words = KEYWORDS[key] || KEYWORDS[LANG_ALIAS[key]] || KEYWORDS.common;\n  const kw = new Set(words.split(' '));\n\n  let comment = '\\\\/\\\\*[\\\\s\\\\S]*?\\\\*\\\\/|\\\\/\\\\/[^\\\\n]*';\n  if (HASH_COMMENT.has(key)) comment = '#[^\\\\n]*';\n  else if (DASH_COMMENT.has(key)) comment = '--[^\\\\n]*|\\\\/\\\\*[\\\\s\\\\S]*?\\\\*\\\\/';\n\n  const re = new RegExp(\n    '(' + comment + ')' +\n    '|(\"(?:\\\\\\\\.|[^\"\\\\\\\\])*\"|\\'(?:\\\\\\\\.|[^\\'\\\\\\\\])*\\')' +\n    '|(\\\\b\\\\d+(?:\\\\.\\\\d+)?\\\\b)' +\n    '|([A-Za-z_$][\\\\w$]*)(?=\\\\s*\\\\()' +\n    '|([A-Za-z_$][\\\\w$]*)',\n    'g',\n  );\n\n  let out = '', last = 0, m;\n  while ((m = re.exec(code)) !== null) {\n    out += esc(code.slice(last, m.index));\n    const body = esc(m[0]);\n    if (m[1])      out += `<span class=\"tok-com\">${body}<\/span>`;\n    else if (m[2]) out += `<span class=\"tok-str\">${body}<\/span>`;\n    else if (m[3]) out += `<span class=\"tok-num\">${body}<\/span>`;\n    else if (m[4]) out += kw.has(m[4]) ? `<span class=\"tok-kw\">${body}<\/span>` : `<span class=\"tok-fn\">${body}<\/span>`;\n    else if (m[5]) out += kw.has(m[5]) ? `<span class=\"tok-kw\">${body}<\/span>` : body;\n    else           out += body;\n    last = m.index + m[0].length;\n  }\n  return out + esc(code.slice(last));\n}\n\nconst safeUrl = (u) => (/^(https?:\\/\\/|mailto:|\\/|#)/i.test(u.trim()) ? u.trim() : '#');\n\nconst CODE_MARK = '';   // private-use sentinels, never present in model output\nconst FENCE_MARK = '';\n\nfunction inline(src) {\n  const code = [];\n  let s = String(src).replace(/`([^`\\n]+)`/g, (_, c) => CODE_MARK + (code.push(c) - 1) + CODE_MARK);\n  s = esc(s);\n  s = s.replace(/!\\[([^\\]]*)\\]\\(([^)\\s]+)[^)]*\\)/g,\n    (_, alt, u) => `<a href=\"${esc(safeUrl(u))}\" target=\"_blank\" rel=\"noopener noreferrer\">[изображение] ${alt || ''}<\/a>`);\n  s = s.replace(/\\[([^\\]]+)\\]\\(([^)\\s]+)[^)]*\\)/g,\n    (_, txt, u) => `<a href=\"${esc(safeUrl(u))}\" target=\"_blank\" rel=\"noopener noreferrer\">${txt}<\/a>`);\n  s = s.replace(/(^|[\\s(])(https?:\\/\\/[^\\s<)]+)/g,\n    (_, pre, u) => `${pre}<a href=\"${esc(u)}\" target=\"_blank\" rel=\"noopener noreferrer\">${u}<\/a>`);\n  s = s.replace(/\\*\\*\\*([^*]+)\\*\\*\\*/g, '<strong><em>$1<\/em><\/strong>');\n  s = s.replace(/\\*\\*([^*]+)\\*\\*/g, '<strong>$1<\/strong>');\n  s = s.replace(/(^|\\W)__([^_]+)__(?=\\W|$)/g, '$1<strong>$2<\/strong>');\n  s = s.replace(/(^|[^*])\\*([^*\\n]+)\\*/g, '$1<em>$2<\/em>');\n  s = s.replace(/(^|\\W)_([^_\\n]+)_(?=\\W|$)/g, '$1<em>$2<\/em>');\n  s = s.replace(/~~([^~]+)~~/g, '<del>$1<\/del>');\n  return s.replace(new RegExp(CODE_MARK + '(\\\\d+)' + CODE_MARK, 'g'),\n    (_, i) => `<code>${esc(code[+i])}<\/code>`);\n}\n\nfunction renderMarkdown(src) {\n  if (!src) return '';\n  // An unterminated fence mid-stream still renders as a code block.\n  if (((src.match(/^```/gm) || []).length) % 2 === 1) src += '\\n```';\n\n  const fences = [];\n  src = src.replace(/^```([^\\n`]*)\\n?([\\s\\S]*?)^```[ \\t]*$/gm, (_, lang, code) => {\n    fences.push({ lang: (lang || '').trim(), code: code.replace(/\\n$/, '') });\n    return FENCE_MARK + (fences.length - 1) + FENCE_MARK;\n  });\n\n  const fenceLine = new RegExp('^' + FENCE_MARK + '(\\\\d+)' + FENCE_MARK + '$');\n  const lines = src.split('\\n');\n  const out = [];\n  let i = 0;\n\n  const isList  = (l) => /^\\s*(?:[-*+]|\\d+[.)])\\s+/.test(l);\n  const isTable = (l, n) => !!l && l.includes('|') && !!n &&\n                            /^\\s*\\|?[\\s:.|-]*-[\\s:|.-]*\\|?\\s*$/.test(n) && n.includes('-');\n\n  while (i < lines.length) {\n    const line = lines[i];\n    if (!line.trim()) { i++; continue; }\n\n    const fence = line.match(fenceLine);\n    if (fence) {\n      const { lang, code } = fences[+fence[1]];\n      out.push(\n        '<div class=\"code-block\"><div class=\"code-head\">' +\n        `<span class=\"code-lang\">${esc(lang || 'code')}<\/span>` +\n        `<button class=\"code-copy\" type=\"button\" data-code=\"${encodeURIComponent(code)}\">` +\n        '<svg viewBox=\"0 0 24 24\"><rect x=\"9\" y=\"9\" width=\"12\" height=\"12\" rx=\"2\"/><path d=\"M5 15V5a2 2 0 012-2h10\"/><\/svg>' +\n        'Копировать код<\/button><\/div>' +\n        `<pre><code>${highlight(code, lang)}<\/code><\/pre><\/div>`,\n      );\n      i++; continue;\n    }\n\n    const h = line.match(/^(#{1,6})\\s+(.*)$/);\n    if (h) {\n      const lvl = Math.min(h[1].length, 4);\n      out.push(`<h${lvl}>${inline(h[2].trim())}<\/h${lvl}>`);\n      i++; continue;\n    }\n\n    if (/^\\s*(?:---+|\\*\\*\\*+|___+)\\s*$/.test(line)) { out.push('<hr>'); i++; continue; }\n\n    if (/^\\s*>\\s?/.test(line)) {\n      const buf = [];\n      while (i < lines.length && /^\\s*>\\s?/.test(lines[i])) buf.push(lines[i++].replace(/^\\s*>\\s?/, ''));\n      out.push(`<blockquote>${renderMarkdown(buf.join('\\n'))}<\/blockquote>`);\n      continue;\n    }\n\n    if (isTable(line, lines[i + 1])) {\n      const cells = (row) => row.replace(/^\\s*\\|/, '').replace(/\\|\\s*$/, '').split('|').map((c) => c.trim());\n      const head = cells(line);\n      i += 2;\n      const body = [];\n      while (i < lines.length && lines[i].includes('|') && lines[i].trim()) body.push(cells(lines[i++]));\n      out.push(\n        `<div class=\"table-wrap\"><table><thead><tr>${head.map((c) => `<th>${inline(c)}<\/th>`).join('')}<\/tr><\/thead>` +\n        `<tbody>${body.map((r) => `<tr>${head.map((_, k) => `<td>${inline(r[k] || '')}<\/td>`).join('')}<\/tr>`).join('')}<\/tbody><\/table><\/div>`,\n      );\n      continue;\n    }\n\n    if (isList(line)) {\n      const buf = [];\n      while (i < lines.length && (isList(lines[i]) || (/^\\s{2,}\\S/.test(lines[i]) && buf.length))) buf.push(lines[i++]);\n      out.push(buildList(buf));\n      continue;\n    }\n\n    const para = [];\n    while (i < lines.length && lines[i].trim() && !isList(lines[i]) &&\n           !/^(#{1,6})\\s/.test(lines[i]) && !/^\\s*>/.test(lines[i]) &&\n           !fenceLine.test(lines[i]) && !isTable(lines[i], lines[i + 1])) {\n      para.push(lines[i++]);\n    }\n    if (para.length) out.push(`<p>${inline(para.join('\\n')).replace(/\\n/g, '<br>')}<\/p>`);\n  }\n  return out.join('');\n}\n\n/** Builds a (possibly nested) list from raw markdown lines. */\nfunction buildList(lines) {\n  const indentOf = (l) => l.match(/^\\s*/)[0].replace(/\\t/g, '  ').length;\n  const bullets = lines.filter((l) => /^\\s*(?:[-*+]|\\d+[.)])\\s+/.test(l));\n  const base = bullets.length ? Math.min(...bullets.map(indentOf)) : 0;\n  const ordered = /^\\s*\\d+[.)]\\s+/.test(bullets[0] || '');\n  const items = [];\n\n  for (const line of lines) {\n    const m = line.match(/^(\\s*)(?:[-*+]|\\d+[.)])\\s+(.*)$/);\n    if (m && indentOf(line) <= base) items.push({ text: m[2], children: [] });\n    else if (items.length) items[items.length - 1].children.push(line.slice(base + 2));\n    else items.push({ text: line.trim(), children: [] });\n  }\n\n  const html = items.map((it) => {\n    let inner = inline(it.text);\n    const kids = it.children.filter((l) => l.trim());\n    if (kids.length) {\n      inner += /^\\s*(?:[-*+]|\\d+[.)])\\s+/.test(kids[0]) ? buildList(kids) : `<br>${inline(kids.join(' '))}`;\n    }\n    return `<li>${inner}<\/li>`;\n  }).join('');\n\n  return ordered ? `<ol>${html}<\/ol>` : `<ul>${html}<\/ul>`;\n}\n\n/* ==============================================================\n   Model catalogue\n   ============================================================== */\nfunction allModels() {\n  const list = [];\n  for (const cat of state.catalog.categories || []) {\n    for (const m of cat.models || []) list.push({ ...m, cat: cat.id, catName: cat.name, icon: cat.icon });\n  }\n  for (const m of state.customModels) {\n    list.push({ ...m, cat: 'custom', catName: 'Мои модели', icon: '⭐', custom: true });\n  }\n  return list;\n}\nfunction modelLabel(id) {\n  const star = state.featured.find((f) => f.id === id);\n  if (star) return `${star.icon} ${star.name}`;\n  const hit = allModels().find((m) => m.id === id);\n  return hit ? hit.name : (id || '—');\n}\n\n/* ==============================================================\n   Starter cards - the four featured models\n   The backend resolves each family to a Model ID that Hugging Face\n   actually serves, and tells us whether it is online.\n   ============================================================== */\nasync function loadFeatured() {\n  try {\n    const res = await fetch('/api/featured');\n    if (!res.ok) throw new Error(String(res.status));\n    const data = await res.json();\n    state.featured = Array.isArray(data.featured) ? data.featured : [];\n  } catch {\n    state.featured = [];\n  }\n}\n\nfunction starterCard(f) {\n  const card = el('button', 'starter');\n  card.dataset.type = f.type || 'normal';\n  card.dataset.key = f.key || '';\n  if (f.id === state.model) card.classList.add('chosen');\n  const online = f.status === 'online';\n\n  card.innerHTML =\n    '<span class=\"s-shine\" aria-hidden=\"true\"><\/span>' +\n    '<span class=\"s-icon\"><\/span>' +\n    '<span class=\"s-body\"><span class=\"s-name\"><\/span><span class=\"s-desc\"><\/span><\/span>' +\n    `<span class=\"s-status ${online ? 'on' : 'off'}\"><i><\/i><span><\/span><\/span>` +\n    '<span class=\"s-id\"><\/span>';\n\n  card.querySelector('.s-icon').textContent = f.icon || '';\n  card.querySelector('.s-name').textContent = f.name || '';\n  card.querySelector('.s-desc').textContent = f.desc || '';\n  card.querySelector('.s-status span').textContent = online ? 'Online' : 'Offline';\n  card.querySelector('.s-id').textContent = f.id || '';\n  card.title = f.id || '';\n\n  card.onclick = () => {\n    setModel(f.id, { silent: true });\n    if (online) {\n      toast('ok', `${f.icon} ${f.name} выбран`, f.id, 2600);\n    } else {\n      toast('err', `${f.name} сейчас офлайн`,\n        'Модель сейчас недоступна через Hugging Face Inference. Выберите другую карточку.', 7000);\n    }\n    closeModal('modelModal');\n    renderChat();\n    renderStarters();\n    $('input').focus();\n  };\n  return card;\n}\n\n/** Repaints every starter grid currently on the page. */\nfunction renderStarters() {\n  for (const box of document.querySelectorAll('.starters')) {\n    box.innerHTML = '';\n    if (!state.featured.length) {\n      box.appendChild(el('div', 'starters-empty', 'Не удалось загрузить список моделей.'));\n      continue;\n    }\n    for (const f of state.featured) box.appendChild(starterCard(f));\n  }\n}\n\n/* ==============================================================\n   Sidebar\n   ============================================================== */\nconst ICON_BUBBLE = '<svg class=\"chat-ico\" viewBox=\"0 0 24 24\"><path d=\"M21 12a8 8 0 01-8 8H7l-4 3v-5.5A8 8 0 1121 12z\"/><\/svg>';\nconst ICON_PEN    = '<svg viewBox=\"0 0 24 24\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 013 3L7 19l-4 1 1-4z\"/><\/svg>';\nconst ICON_TRASH  = '<svg viewBox=\"0 0 24 24\"><path d=\"M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14\"/><\/svg>';\n\nfunction renderSidebar() {\n  const box = $('chatList');\n  box.innerHTML = '';\n\n  const q = state.filter.trim().toLowerCase();\n  const chats = [...state.chats]\n    .sort((a, b) => b.updatedAt - a.updatedAt)\n    .filter((c) => {\n      if (!q) return true;\n      if (c.title.toLowerCase().includes(q)) return true;\n      return c.messages.some((m) => (m.content || '').toLowerCase().includes(q));\n    });\n\n  if (!chats.length) {\n    box.appendChild(el('div', 'empty-history',\n      q ? 'Ничего не найдено' : 'Пока нет чатов.\\nНачните первый разговор.'));\n    return;\n  }\n\n  for (const chat of chats) {\n    const item = el('div', 'chat-item' + (chat.id === state.currentId ? ' active' : ''));\n    item.innerHTML = ICON_BUBBLE;\n\n    const title = el('button', 'chat-title', chat.title);\n    title.title = chat.title;\n    title.onclick = () => { openChat(chat.id); closeSidebar(); };\n    item.appendChild(title);\n\n    const acts = el('div', 'chat-acts');\n    const ren = el('button', 'ren'); ren.innerHTML = ICON_PEN; ren.title = 'Переименовать';\n    ren.onclick = (e) => { e.stopPropagation(); askRename(chat.id); };\n    const del = el('button', 'del'); del.innerHTML = ICON_TRASH; del.title = 'Удалить';\n    del.onclick = (e) => { e.stopPropagation(); deleteChat(chat.id); };\n    acts.append(ren, del);\n    item.appendChild(acts);\n\n    box.appendChild(item);\n  }\n}\n\n/* ==============================================================\n   Chat lifecycle\n   ============================================================== */\nfunction newChat() {\n  stopStream();\n  const chat = {\n    id: uid(),\n    title: 'Новый чат',\n    model: state.model,\n    createdAt: Date.now(),\n    updatedAt: Date.now(),\n    messages: [],\n  };\n  state.chats.unshift(chat);\n  state.currentId = chat.id;\n  persistChats();\n  renderSidebar();\n  renderChat();\n  $('input').focus();\n  return chat;\n}\n\nfunction openChat(id) {\n  stopStream();\n  state.currentId = id;\n  const chat = currentChat();\n  if (chat && chat.model) setModel(chat.model, { silent: true, persistChat: false });\n  persistChats();\n  renderSidebar();\n  renderChat();\n}\n\nfunction deleteChat(id) {\n  const chat = state.chats.find((c) => c.id === id);\n  if (!chat) return;\n  if (!confirm(`Удалить чат «${chat.title}»?`)) return;\n  state.chats = state.chats.filter((c) => c.id !== id);\n  if (state.currentId === id) state.currentId = state.chats.length ? state.chats[0].id : null;\n  persistChats();\n  renderSidebar();\n  renderChat();\n  toast('ok', 'Чат удалён', '', 2200);\n}\n\nfunction clearAllChats() {\n  if (!state.chats.length) { toast('info', 'История уже пуста', '', 2200); return; }\n  if (!confirm('Удалить всю историю чатов? Это действие нельзя отменить.')) return;\n  stopStream();\n  state.chats = [];\n  state.currentId = null;\n  persistChats();\n  renderSidebar();\n  renderChat();\n  toast('ok', 'История очищена', '', 2200);\n}\n\nfunction askRename(id) {\n  const chat = state.chats.find((c) => c.id === id);\n  if (!chat) return;\n  state.renameTarget = id;\n  $('renameInput').value = chat.title;\n  openModal('renameModal');\n  setTimeout(() => { $('renameInput').focus(); $('renameInput').select(); }, 60);\n}\n\nfunction commitRename() {\n  const chat = state.chats.find((c) => c.id === state.renameTarget);\n  const name = $('renameInput').value.trim();\n  if (chat && name) {\n    chat.title = name.slice(0, 80);\n    chat.updatedAt = Date.now();\n    persistChats();\n    renderSidebar();\n  }\n  closeModal('renameModal');\n}\n\n/* ==============================================================\n   Message rendering\n   ============================================================== */\nconst ICONS = {\n  copy:   '<svg viewBox=\"0 0 24 24\"><rect x=\"9\" y=\"9\" width=\"12\" height=\"12\" rx=\"2\"/><path d=\"M5 15V5a2 2 0 012-2h10\"/><\/svg>',\n  redo:   '<svg viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 11-3-6.7\"/><path d=\"M21 4v5h-5\"/><\/svg>',\n  up:     '<svg viewBox=\"0 0 24 24\"><path d=\"M7 21V10l5-8a2 2 0 013 2l-1 6h5a2 2 0 012 2.4l-1.6 7A2 2 0 0117 21z\"/><\/svg>',\n  down:   '<svg viewBox=\"0 0 24 24\"><path d=\"M17 3v11l-5 8a2 2 0 01-3-2l1-6H5a2 2 0 01-2-2.4l1.6-7A2 2 0 017 3z\"/><\/svg>',\n};\n\nconst QUICK = [\n  { emoji: '\\u{1F4BB}', label: 'Написать код',        prompt: 'Напиши функцию на Python, которая читает CSV-файл и возвращает статистику по числовым колонкам. Добавь комментарии.' },\n  { emoji: '\\u{1F3AE}', label: 'Помочь с Minecraft',  prompt: 'Объясни, как сделать автоматическую ферму железа в Minecraft 1.21. Пошагово и со списком ресурсов.' },\n  { emoji: '\\u{1F4DA}', label: 'Объяснить тему',      prompt: 'Объясни простыми словами, как работают нейронные сети. Приведи аналогию и небольшую таблицу с терминами.' },\n  { emoji: '\\u{1F4A1}', label: 'Придумать идею',      prompt: 'Придумай 5 оригинальных идей для пет-проекта на выходные. Для каждой укажи стек и сложность.' },\n];\n\nfunction welcomeNode() {\n  const w = el('div', 'welcome');\n  w.innerHTML =\n    '<div class=\"welcome-logo\" aria-hidden=\"true\"><\/div>' +\n    '<h1>Multi AI Chat<\/h1>' +\n    '<p>Выберите нейросеть и начните общение<\/p>';\n\n  const starters = el('div', 'starters');\n  w.appendChild(starters);\n\n  const quickLabel = el('div', 'quick-label', 'Или начните с готового вопроса');\n  w.appendChild(quickLabel);\n\n  const grid = el('div', 'quick');\n  for (const q of QUICK) {\n    const b = el('button');\n    b.innerHTML = `<span class=\"emoji\">${q.emoji}<\/span><span><\/span>`;\n    b.querySelector('span:last-child').textContent = q.label;\n    b.onclick = () => {\n      const ta = $('input');\n      ta.value = q.prompt;\n      autoGrow(ta);\n      ta.focus();\n      refreshSendState();\n    };\n    grid.appendChild(b);\n  }\n  w.appendChild(grid);\n  return w;\n}\n\nfunction messageNode(msg, chat) {\n  const wrap = el('div', `msg ${msg.role === 'user' ? 'user' : 'ai'}`);\n  wrap.dataset.id = msg.id;\n\n  const av = el('div', 'avatar', msg.role === 'user' ? 'Вы' : '');\n  if (msg.role !== 'user') {\n    av.innerHTML = '<svg viewBox=\"0 0 24 24\" style=\"width:17px;height:17px\"><path d=\"M12 3l2.2 5.8L20 11l-5.8 2.2L12 19l-2.2-5.8L4 11l5.8-2.2z\"/><\/svg>';\n  }\n  wrap.appendChild(av);\n\n  const col = el('div', 'bubble-col');\n  const bubble = el('div', 'bubble' + (msg.error ? ' error' : ''));\n\n  if (msg.role === 'user') {\n    bubble.textContent = msg.content;\n  } else {\n    bubble.classList.add('md');\n    paintAssistant(bubble, msg);\n  }\n  col.appendChild(bubble);\n\n  if (msg.role === 'assistant' && !msg.streaming) {\n    col.appendChild(assistantActions(msg, chat));\n  }\n\n  wrap.appendChild(col);\n  return wrap;\n}\n\nfunction paintAssistant(bubble, msg) {\n  if (msg.error) {\n    bubble.innerHTML = '<span class=\"err-title\"><\/span><span class=\"err-text\"><\/span>';\n    bubble.querySelector('.err-title').textContent = 'Ошибка';\n    bubble.querySelector('.err-text').textContent = msg.content;\n    return;\n  }\n  if (msg.streaming && !msg.content && !msg.reasoning) {\n    bubble.innerHTML =\n      '<span class=\"typing\">AI печатает<span class=\"dots\"><i><\/i><i><\/i><i><\/i><\/span><\/span>';\n    return;\n  }\n  let html = '';\n  if (msg.reasoning) html += `<div class=\"reasoning\">${esc(msg.reasoning)}<\/div>`;\n  html += renderMarkdown(msg.content || '');\n  if (msg.streaming) html += '<span class=\"caret\"><\/span>';\n  bubble.innerHTML = html;\n  wireCodeCopy(bubble);\n}\n\nfunction wireCodeCopy(root) {\n  root.querySelectorAll('.code-copy').forEach((btn) => {\n    if (btn.dataset.wired) return;\n    btn.dataset.wired = '1';\n    btn.onclick = () => copyText(decodeURIComponent(btn.dataset.code), 'Код скопирован');\n  });\n}\n\nfunction assistantActions(msg, chat) {\n  const bar = el('div', 'msg-acts');\n\n  const mk = (cls, icon, label, title) => {\n    const b = el('button', `act ${cls}`);\n    b.innerHTML = icon + `<span>${label}<\/span>`;\n    b.title = title || label;\n    return b;\n  };\n\n  const copy = mk('', ICONS.copy, 'Копировать');\n  copy.onclick = () => copyText(msg.content);\n  bar.appendChild(copy);\n\n  const redo = mk('', ICONS.redo, 'Повторить ответ');\n  redo.onclick = () => regenerate(msg.id);\n  bar.appendChild(redo);\n\n  if (!msg.error) {\n    const up = mk(msg.feedback === 'up' ? 'on' : '', ICONS.up, '', 'Хороший ответ');\n    up.innerHTML = ICONS.up;\n    up.onclick = () => setFeedback(msg, chat, 'up');\n    const down = mk(msg.feedback === 'down' ? 'on down' : '', ICONS.down, '', 'Плохой ответ');\n    down.innerHTML = ICONS.down;\n    down.onclick = () => setFeedback(msg, chat, 'down');\n    bar.append(up, down);\n  }\n  return bar;\n}\n\nfunction setFeedback(msg, chat, value) {\n  msg.feedback = msg.feedback === value ? null : value;\n  chat.updatedAt = Date.now();\n  persistChats();\n  renderChat();\n  if (msg.feedback) toast('ok', msg.feedback === 'up' ? 'Спасибо за оценку' : 'Оценка учтена', '', 1600);\n}\n\nfunction renderChat() {\n  const box = $('messages');\n  const chat = currentChat();\n  box.innerHTML = '';\n\n  if (!chat || !chat.messages.length) {\n    box.appendChild(welcomeNode());\n    renderStarters();\n    updateTopbar();\n    return;\n  }\n\n  const thread = el('div', 'thread');\n  for (const msg of chat.messages) thread.appendChild(messageNode(msg, chat));\n  box.appendChild(thread);\n  scrollToBottom(true);\n  updateTopbar();\n}\n\nfunction nearBottom() {\n  const b = $('messages');\n  return b.scrollHeight - b.scrollTop - b.clientHeight < 140;\n}\nfunction scrollToBottom(force) {\n  const b = $('messages');\n  if (force || nearBottom()) b.scrollTop = b.scrollHeight;\n}\n\nfunction updateTopbar() {\n  $('modelName').textContent = modelLabel(state.model);\n  $('modelName').title = state.model || '';\n}\nfunction setStatus(kind, text) {\n  const s = $('modelStatus');\n  s.className = 'model-status' + (kind ? ` ${kind}` : '');\n  $('statusText').textContent = text;\n}\n\n/* ==============================================================\n   Sending / streaming\n   ============================================================== */\nfunction buildHistory(chat, upto) {\n  const msgs = [];\n  const sys = state.settings.systemPrompt.trim();\n  if (sys) msgs.push({ role: 'system', content: sys });\n  for (const m of chat.messages.slice(0, upto)) {\n    if (m.error || m.streaming) continue;\n    if (!m.content) continue;\n    msgs.push({ role: m.role, content: m.content });\n  }\n  return msgs;\n}\n\nasync function send(text) {\n  const body = (text ?? $('input').value).trim();\n  if (!body || state.abort) return;\n  if (!state.model) { toast('err', 'Модель не выбрана', 'Нажмите «Выбрать модель».'); return; }\n\n  let chat = currentChat();\n  if (!chat) chat = newChat();\n\n  chat.messages.push({ id: uid(), role: 'user', content: body });\n  if (chat.title === 'Новый чат') {\n    chat.title = body.replace(/\\s+/g, ' ').slice(0, 48) + (body.length > 48 ? '…' : '');\n  }\n  chat.model = state.model;\n  chat.updatedAt = Date.now();\n\n  const ta = $('input');\n  ta.value = '';\n  autoGrow(ta);\n  refreshSendState();\n\n  const reply = { id: uid(), role: 'assistant', content: '', streaming: true };\n  chat.messages.push(reply);\n\n  persistChats();\n  renderSidebar();\n  renderChat();\n\n  await runCompletion(chat, reply);\n}\n\nasync function regenerate(msgId) {\n  if (state.abort) return;\n  const chat = currentChat();\n  if (!chat) return;\n  const idx = chat.messages.findIndex((m) => m.id === msgId);\n  if (idx < 0) return;\n\n  const reply = chat.messages[idx];\n  reply.content = '';\n  reply.reasoning = '';\n  reply.error = false;\n  reply.feedback = null;\n  reply.streaming = true;\n  chat.messages.length = idx + 1;\n\n  renderChat();\n  await runCompletion(chat, reply);\n}\n\nasync function runCompletion(chat, reply) {\n  const idx = chat.messages.indexOf(reply);\n  const history = buildHistory(chat, idx);\n\n  const controller = new AbortController();\n  state.abort = controller;\n  $('stopBtn').hidden = false;\n  refreshSendState();\n  setStatus('busy', 'Генерация…');\n\n  const bubble = () => {\n    const node = $('messages').querySelector(`.msg[data-id=\"${reply.id}\"] .bubble`);\n    return node;\n  };\n\n  let painted = 0;\n  const repaint = (force) => {\n    const now = Date.now();\n    if (!force && now - painted < 55) return;\n    painted = now;\n    const b = bubble();\n    if (b) { paintAssistant(b, reply); scrollToBottom(false); }\n  };\n\n  try {\n    const res = await fetch('/api/chat', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      signal: controller.signal,\n      body: JSON.stringify({\n        model: state.model,\n        messages: history,\n        temperature: state.settings.temperature,\n        max_tokens: state.settings.maxTokens,\n        top_p: state.settings.topP,\n        stream: true,\n      }),\n    });\n\n    if (!res.ok && !(res.headers.get('content-type') || '').includes('text/event-stream')) {\n      let message = `Сервер вернул ${res.status}`;\n      try {\n        const data = await res.json();\n        if (data && data.error && data.error.message) message = data.error.message;\n      } catch { /* keep the status-based message */ }\n      throw new StreamError(message);\n    }\n\n    const reader = res.body.getReader();\n    const decoder = new TextDecoder();\n    let buffer = '';\n\n    for (;;) {\n      const { value, done } = await reader.read();\n      if (done) break;\n      buffer += decoder.decode(value, { stream: true });\n\n      const parts = buffer.split('\\n\\n');\n      buffer = parts.pop() || '';\n\n      for (const part of parts) {\n        const line = part.split('\\n').find((l) => l.startsWith('data:'));\n        if (!line) continue;\n        let evt;\n        try { evt = JSON.parse(line.slice(5).trim()); } catch { continue; }\n\n        if (evt.type === 'delta') { reply.content += evt.content; repaint(false); }\n        else if (evt.type === 'reasoning') { reply.reasoning = (reply.reasoning || '') + evt.content; repaint(false); }\n        else if (evt.type === 'error') { throw new StreamError(evt.message, evt.code); }\n      }\n    }\n\n    reply.streaming = false;\n    if (!reply.content.trim()) {\n      reply.error = true;\n      reply.content = 'Модель вернула пустой ответ. Попробуйте ещё раз или выберите другую модель.';\n    }\n    setStatus('', 'Online');\n  } catch (err) {\n    reply.streaming = false;\n    if (err && err.name === 'AbortError') {\n      if (!reply.content.trim()) {\n        reply.error = true;\n        reply.content = 'Генерация остановлена.';\n      }\n      setStatus('', 'Online');\n    } else {\n      const message = err instanceof StreamError\n        ? err.message\n        : 'Не удалось связаться с сервером. Проверьте интернет-соединение.';\n      reply.error = true;\n      reply.content = message;\n      setStatus('err', 'Ошибка');\n      toast('err', errorTitle(err), message, 8000);\n    }\n  } finally {\n    state.abort = null;\n    $('stopBtn').hidden = true;\n    chat.updatedAt = Date.now();\n    persistChats();\n    renderSidebar();\n    renderChat();\n    refreshSendState();\n  }\n}\n\nclass StreamError extends Error {\n  constructor(message, code) { super(message); this.name = 'StreamError'; this.code = code; }\n}\n\nfunction errorTitle(err) {\n  const map = {\n    bad_token: 'Проблема с токеном',\n    no_token: 'HF_TOKEN не задан',\n    model_unavailable: 'Модель недоступна',\n    model_gated: 'Закрытая модель',\n    model_loading: 'Модель загружается',\n    rate_limit: 'Лимит запросов',\n    timeout: 'Таймаут',\n    network: 'Ошибка сети',\n  };\n  return (err && map[err.code]) || 'Ошибка';\n}\n\nfunction stopStream() {\n  if (state.abort) { state.abort.abort(); state.abort = null; }\n  $('stopBtn').hidden = true;\n}\n\n/* ==============================================================\n   Model picker\n   ============================================================== */\nfunction openPicker() {\n  state.modelFilter = '';\n  $('modelSearch').value = '';\n  renderPicker();\n  openModal('modelModal');\n}\n\nfunction renderPicker() {\n  renderStarters();\n  const cats = $('pickerCats');\n  const box = $('pickerModels');\n  const q = state.modelFilter.trim().toLowerCase();\n  const models = allModels();\n\n  const groups = [{ id: 'all', name: 'Все модели', icon: '✨' }];\n  for (const c of state.catalog.categories || []) groups.push({ id: c.id, name: c.name, icon: c.icon });\n  if (state.customModels.length) groups.push({ id: 'custom', name: 'Мои модели', icon: '⭐' });\n\n  cats.innerHTML = '';\n  for (const g of groups) {\n    const n = g.id === 'all' ? models.length : models.filter((m) => m.cat === g.id).length;\n    const b = el('button', state.activeCat === g.id ? 'active' : '');\n    b.innerHTML = `<span>${g.icon || ''}<\/span><span><\/span><span class=\"count\">${n}<\/span>`;\n    b.querySelectorAll('span')[1].textContent = g.name;\n    b.onclick = () => { state.activeCat = g.id; renderPicker(); };\n    cats.appendChild(b);\n  }\n\n  const visible = models.filter((m) => {\n    const inCat = state.activeCat === 'all' || m.cat === state.activeCat;\n    if (!q) return inCat;\n    return (m.name + ' ' + m.id + ' ' + (m.desc || '')).toLowerCase().includes(q);\n  });\n\n  box.innerHTML = '';\n  if (!visible.length) {\n    box.appendChild(el('div', 'picker-empty',\n      'Ничего не найдено. Добавьте модель по Model ID внизу окна.'));\n    return;\n  }\n\n  for (const m of visible) {\n    const card = el('div', 'model-card' + (m.id === state.model ? ' active' : ''));\n\n    const body = el('div', 'mc-body');\n    body.appendChild(el('div', 'mc-name', `${m.icon || ''} ${m.name}`.trim()));\n    const id = el('div', 'mc-id', m.id); id.title = m.id;\n    body.appendChild(id);\n    if (m.desc) body.appendChild(el('div', 'mc-desc', m.desc));\n    card.appendChild(body);\n\n    if (m.custom) {\n      const del = el('button', 'mc-del');\n      del.innerHTML = ICON_TRASH;\n      del.title = 'Убрать из списка';\n      del.onclick = (e) => {\n        e.stopPropagation();\n        state.customModels = state.customModels.filter((x) => x.id !== m.id);\n        save(LS.custom, state.customModels);\n        renderPicker();\n        toast('ok', 'Модель убрана', m.id, 2400);\n      };\n      card.appendChild(del);\n    }\n\n    const check = el('div', 'mc-check');\n    check.innerHTML = '<svg viewBox=\"0 0 24 24\"><path d=\"M20 6L9 17l-5-5\"/><\/svg>';\n    card.appendChild(check);\n\n    card.onclick = () => { setModel(m.id); closeModal('modelModal'); };\n    box.appendChild(card);\n  }\n}\n\nfunction setModel(id, opts = {}) {\n  state.model = id;\n  save(LS.model, id);\n  const chat = currentChat();\n  if (chat && opts.persistChat !== false) { chat.model = id; persistChats(); }\n  updateTopbar();\n  setStatus('', 'Online');\n  if (!opts.silent) toast('ok', 'Модель выбрана', `${modelLabel(id)} — ${id}`, 2600);\n}\n\nfunction addCustomModel() {\n  const input = $('customModel');\n  const id = input.value.trim();\n  if (!id) return;\n  if (!/^[A-Za-z0-9._-]+\\/[A-Za-z0-9._-]+(:[A-Za-z0-9._-]+)?$/.test(id)) {\n    toast('err', 'Неверный Model ID', 'Формат: owner/name, например Qwen/Qwen2.5-7B-Instruct');\n    return;\n  }\n  if (allModels().some((m) => m.id === id)) {\n    toast('info', 'Эта модель уже в списке', id, 2600);\n    setModel(id); closeModal('modelModal'); return;\n  }\n  state.customModels.push({ id, name: id.split('/').pop(), desc: 'Добавлена вручную' });\n  save(LS.custom, state.customModels);\n  input.value = '';\n  state.activeCat = 'custom';\n  renderPicker();\n  setModel(id);\n  closeModal('modelModal');\n  toast('ok', 'Модель добавлена', id, 3000);\n}\n\n/* ==============================================================\n   Settings\n   ============================================================== */\nfunction renderThemes() {\n  const box = $('themePicker');\n  if (!box) return;\n  box.innerHTML = '';\n  for (const t of THEMES) {\n    const b = el('button', state.settings.theme === t.id ? 'active' : '');\n    b.type = 'button';\n    b.dataset.t = t.id;\n    b.innerHTML = '<span class=\"t-swatch\"><\/span><span><\/span>';\n    b.querySelectorAll('span')[1].textContent = t.name;\n    b.onclick = () => {\n      state.settings.theme = t.id;\n      save(LS.settings, state.settings);\n      applyTheme(t.id);\n      renderThemes();\n      toast('ok', `Стиль: ${t.name}`, '', 1800);\n    };\n    box.appendChild(b);\n  }\n}\n\nfunction fillSettings() {\n  renderThemes();\n  $('systemPrompt').value = state.settings.systemPrompt;\n  $('temperature').value = state.settings.temperature;\n  $('maxTokens').value = state.settings.maxTokens;\n  $('topP').value = state.settings.topP;\n  $('temperatureOut').textContent = Number(state.settings.temperature).toFixed(2);\n  $('maxTokensOut').textContent = state.settings.maxTokens;\n  $('topPOut').textContent = Number(state.settings.topP).toFixed(2);\n}\n\nfunction wireSettings() {\n  $('systemPrompt').oninput = (e) => { state.settings.systemPrompt = e.target.value; save(LS.settings, state.settings); };\n  const bind = (id, outId, key, fmt) => {\n    $(id).oninput = (e) => {\n      const v = Number(e.target.value);\n      state.settings[key] = v;\n      $(outId).textContent = fmt ? fmt(v) : v;\n      save(LS.settings, state.settings);\n    };\n  };\n  bind('temperature', 'temperatureOut', 'temperature', (v) => v.toFixed(2));\n  bind('maxTokens', 'maxTokensOut', 'maxTokens');\n  bind('topP', 'topPOut', 'topP', (v) => v.toFixed(2));\n\n  $('resetSettings').onclick = () => {\n    state.settings = { ...DEFAULT_SETTINGS };\n    save(LS.settings, state.settings);\n    applyTheme(state.settings.theme);\n    fillSettings();\n    toast('ok', 'Настройки сброшены', '', 2200);\n  };\n}\n\n/* ==============================================================\n   Modals / sidebar helpers\n   ============================================================== */\nfunction openModal(id) { $(id).hidden = false; }\nfunction closeModal(id) { $(id).hidden = true; }\nfunction openSidebar() { $('sidebar').classList.add('open'); $('scrim').hidden = false; }\nfunction closeSidebar() { $('sidebar').classList.remove('open'); $('scrim').hidden = true; }\n\nfunction autoGrow(ta) {\n  ta.style.height = 'auto';\n  ta.style.height = Math.min(ta.scrollHeight, 210) + 'px';\n}\nfunction refreshSendState() {\n  $('sendBtn').disabled = !$('input').value.trim() || !!state.abort;\n}\n\n/* ==============================================================\n   Boot\n   ============================================================== */\nasync function loadCatalog() {\n  try {\n    const res = await fetch('/api/models');\n    if (!res.ok) throw new Error(String(res.status));\n    state.catalog = await res.json();\n  } catch {\n    toast('err', 'Каталог моделей недоступен', 'Не удалось загрузить список моделей с сервера.');\n  }\n  if (!state.model || !allModels().some((m) => m.id === state.model)) {\n    state.model = state.model || state.catalog.default;\n  }\n  updateTopbar();\n}\n\nasync function checkHealth() {\n  try {\n    const res = await fetch('/api/health');\n    const data = await res.json();\n    if (!data.token_configured) {\n      setStatus('err', 'HF_TOKEN не задан');\n      // The hint comes from the backend, so the hosted site and the browser\n      // extension can each say where the token actually belongs.\n      toast('err', 'HF_TOKEN не настроен',\n        data.hint || 'Добавьте секрет HF_TOKEN в настройках хостинга и перезапустите приложение.',\n        12000);\n    } else {\n      setStatus('', 'Online');\n    }\n  } catch {\n    setStatus('err', 'Сервер недоступен');\n  }\n}\n\nfunction wireEvents() {\n  $('newChatBtn').onclick = () => { newChat(); closeSidebar(); };\n  $('menuBtn').onclick = openSidebar;\n  $('sidebarClose').onclick = closeSidebar;\n  $('scrim').onclick = closeSidebar;\n\n  $('searchInput').oninput = (e) => { state.filter = e.target.value; renderSidebar(); };\n\n  $('settingsBtn').onclick = () => { fillSettings(); openModal('settingsModal'); closeSidebar(); };\n  $('clearAllBtn').onclick = () => { clearAllChats(); closeSidebar(); };\n\n  $('pickModelBtn').onclick = openPicker;\n  $('modelSearch').oninput = (e) => { state.modelFilter = e.target.value; renderPicker(); };\n  $('addModelBtn').onclick = addCustomModel;\n  $('customModel').onkeydown = (e) => { if (e.key === 'Enter') addCustomModel(); };\n\n  $('renameSave').onclick = commitRename;\n  $('renameInput').onkeydown = (e) => { if (e.key === 'Enter') commitRename(); };\n\n  document.querySelectorAll('[data-close]').forEach((b) => {\n    b.onclick = () => { const m = b.closest('.modal'); if (m) m.hidden = true; };\n  });\n  document.querySelectorAll('.modal').forEach((m) => {\n    m.addEventListener('click', (e) => { if (e.target === m) m.hidden = true; });\n  });\n  document.addEventListener('keydown', (e) => {\n    if (e.key !== 'Escape') return;\n    const open = [...document.querySelectorAll('.modal')].find((m) => !m.hidden);\n    if (open) open.hidden = true;\n    else closeSidebar();\n  });\n\n  const ta = $('input');\n  ta.addEventListener('input', () => { autoGrow(ta); refreshSendState(); });\n  ta.addEventListener('keydown', (e) => {\n    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); send(); }\n  });\n  $('sendBtn').onclick = () => send();\n  $('stopBtn').onclick = stopStream;\n}\n\nasync function boot() {\n  wireEvents();\n  wireSettings();\n  fillSettings();\n  renderSidebar();\n  renderChat();\n  refreshSendState();\n  await Promise.all([loadCatalog(), loadFeatured()]);\n  renderChat();\n  renderStarters();\n  checkHealth();\n}\n\ndocument.addEventListener('DOMContentLoaded', boot);\n"};
